    let (kind, rest) = match s.chars().next().unwrap() {
        '+' => ('+', &s[1..]),
        '-' => ('-', &s[1..]),
        _ => ('=', s),
    };
    if rest.is_empty() {
        return Err(format!("'{}' is not a valid size constraint. See 'fd --help'.", s));
    }
    // Find where numeric ends and unit begins
    let mut num_end = 0;
    for (i, c) in rest.char_indices() {
        if c.is_ascii_digit() {
            num_end = i + c.len_utf8();
        } else {
            break;
        }
    }
    if num_end == 0 {
        return Err(format!("'{}' is not a valid size constraint. See 'fd --help'.", s));
    }
    let num_str = &rest[..num_end];
    let unit_str = rest[num_end..].trim().to_lowercase();
    let num: u64 = num_str.parse().map_err(|_| format!("'{}' is not a valid size constraint. See 'fd --help'.", s))?;
    let multiplier: u64 = match unit_str.as_str() {
