    };

    if owner_str.contains(':') {
        let parts: Vec<&str> = owner_str.splitn(2, ':').collect();
        let user_part = parts[0];
        let group_part = parts[1];
        // user part
        if !user_part.is_empty() {
            let (neg, name) = if user_part.starts_with('!') {
                (true, &user_part[1..])
            } else {
                (false, user_part)
            };
            if name.is_empty() {
                return Err(format!("'' is not a recognized user name"));
            }
            if let Ok(uid) = name.parse::<u32>() {
                filter.uid = Some((uid, neg));
            } else {
                // check if valid user name? If not found, error?
                // Original fd errors for invalid user name? In earlier test, "! :group" with empty after ! gave error.
                // We'll attempt to resolve name to uid for later check, but also store name for error handling? For now store name
                filter.user_name = Some((name.to_string(), neg));
            }
        }
        if !group_part.is_empty() {
            let (neg, name) = if group_part.starts_with('!') {
                (true, &group_part[1..])
            } else {
                (false, group_part)
            };
            if name.is_empty() {
                return Err(format!("'' is not a recognized group name"));
            }
            if let Ok(gid) = name.parse::<u32>() {
                filter.gid = Some((gid, neg));
            } else {
                filter.group_name = Some((name.to_string(), neg));
            }
        }
    } else {
        // Only user part
        let (neg, name) = if owner_str.starts_with('!') {
            (true, &owner_str[1..])
        } else {
            (false, owner_str)
        };
        if name.is_empty() {
            return Err(format!("'' is not a recognized user name"));
        }
        if let Ok(uid) = name.parse::<u32>() {
            filter.uid = Some((uid, neg));
        } else {
            filter.user_name = Some((name.to_string(), neg));
        }
    }

    Ok(filter)
}

fn check_owner(meta: &fs::Metadata, filter: &OwnerFilter) -> bool {
    let uid = meta.uid();
    let gid = meta.gid();

    // Check uid
    let uid_match = if let Some((filter_uid, neg)) = filter.uid {
        let matches = uid == filter_uid;
        if neg { !matches } else { matches }
    } else if let Some((ref name, neg)) = filter.user_name {
        if let Some(filter_uid) = get_uid_by_name(name) {
            let matches = uid == filter_uid;
            if neg { !matches } else { matches }
        } else {
            // If user name not found, then no file can match unless negated? Actually if user doesn't exist, then no file matches that user, so if negated, all files match? Let's think.
            // If filter is !nonexistent, then all files should match (since none have that user). If filter is nonexistent without !, then none match.
            if neg { true } else { false }
        }
    } else {
        true // no uid filter
    };

    let gid_match = if let Some((filter_gid, neg)) = filter.gid {
        let matches = gid == filter_gid;
        if neg { !matches } else { matches }
    } else if let Some((ref name, neg)) = filter.group_name {
        if let Some(filter_gid) = get_gid_by_name(name) {
            let matches = gid == filter_gid;
            if neg { !matches } else { matches }
        } else {
            if neg { true } else { false }
        }
    } else {
        true
    };

    uid_match && gid_match
}

fn main() {
    let mut cmd = Command::new("fd")
        .version("10.3.0")
