fn get_hostname() -> String {
    // Try to get hostname via /etc/hostname or gethostname syscall
    // For simplicity, use std::fs read /etc/hostname or use "localhost"
    // Original fd uses hostname from gethostname? In earlier output, hostname was e835cbd14a34 (docker container id)
    // We can try to get from env or file
    if let Ok(content) = fs::read_to_string("/etc/hostname") {
        return content.trim().to_string();
    }
    // Try to read from /proc/sys/kernel/hostname
    if let Ok(content) = fs::read_to_string("/proc/sys/kernel/hostname") {
        return content.trim().to_string();
    }
    // Fallback to using gethostname via libc? We'll just try to get from env HOSTNAME
    if let Ok(h) = std::env::var("HOSTNAME") {
        return h;
    }
    "localhost".to_string()
}

fn colorize_path(path: &Path, display: &str) -> String {
    // Implement simple colorization matching observed fd behavior
    // We need to map file types/extensions to colors
