            if display.ends_with("/") || display.ends_with(std::path::MAIN_SEPARATOR.to_string().as_str()) {
                // Directory
                // For display like "a/b/" we should color "a/" and "b/" separately? But we saw earlier output for dir: "a/b/" was colored as "a/b/" in dir color? Actually earlier we saw for file "a/b/file3.txt", output was: "^[[38;5;81ma/b/^[[0m^[[38;5;185mfile3.txt^[[0m" -> dir part "a/b/" colored 81, file colored 185.
                // For directory "a/b/" itself, what would fd show? Let's test: cd /tmp/test_flag; fd -c always --type d -> we saw earlier it shows "a/" in dir color, "a/b/" etc all in dir color? Probably yes.
                // So for dir, color whole as dir.

                // For simplicity, color whole display as dir color
                return format!("\x1b[38;5;81m{}\x1b[0m", display);
            }
        }
        if m.is_dir() {
            return format!("\x1b[38;5;81m{}\x1b[0m", display);
        }
        // Check if executable
        if m.is_file() {
            let mode = m.mode();
            if mode & 0o111 != 0 {
                // executable (bold + 203)
                return format!("\x1b[1;38;5;203m{}\x1b[0m", display);
            }
        }
        // Check pipe, socket, etc.
        let mode = m.mode();
        if mode & 0o170000 == 0o10000 { // FIFO
            return format!("\x1b[48;5;81;38;5;16m{}\x1b[0m", display);
        }
        if mode & 0o170000 == 0o140000 { // socket
            return format!("\x1b[48;5;203;38;5;16m{}\x1b[0m", display); // similar to broken?
        }
    }

    // For regular file, check extension
    let path_str = path.to_string_lossy().to_lowercase();
    // Extract extension
    let ext = Path::new(&path_str).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();

    // Map extension to color
    // Archive: tar, tgz, zip, gz, bz2, etc.
    let archive_exts = ["tar","tgz","zip","gz","bz","bz2","xz","7z","rar","deb","rpm","jar","z"];
    let media_exts = ["jpg","jpeg","png","gif","bmp","ppm","tga","xbm","xpm","tif","tiff","svg","svgz","mng","pcx","mov","mpg","mpeg","m2v","mkv","webm","ogm","mp4","m4v","mp4v","vob","qt","nuv","wmv","asf","rm","rmvb","flc","avi","fli","flv","gl","dl","xcf","xwd","yuv","cgm","emf","ogv","ogx","aac","au","flac","m4a","mid","midi","mka","mp3","mpc","ogg","ra","wav","oga","opus","spx","xspf"];
