#[derive(Debug, Clone)]
struct SizeFilter {
    kind: char, // '+' '-' or '=' (exact)
    size: u64,
}

fn parse_size(s: &str) -> Result<SizeFilter, String> {
    // format: [+|-]NUM[UNIT]
    // UNIT: b, k, m, g, t, ki, mi, gi, ti (case-insensitive)
    let s = s.trim();
    if s.is_empty() {
        return Err(format!("'{}' is not a valid size constraint. See 'fd --help'.", s));
    }
    let (kind, rest) = match s.chars().next().unwrap() {
        '+' => ('+', &s[1..]),
        '-' => ('-', &s[1..]),
        _ => ('=', s),
    };
    if rest.is_empty() {
        return Err(format!("'{}' is not a valid size constraint. See 'fd --help'.", s));
    }
    // Find where numeric ends and unit begins
    let mut num_end = 0;
    for (i, c) in rest.char_indices() {
        if c.is_ascii_digit() {
            num_end = i + c.len_utf8();
        } else {
            break;
        }
    }
    if num_end == 0 {
        return Err(format!("'{}' is not a valid size constraint. See 'fd --help'.", s));
    }
    let num_str = &rest[..num_end];
    let unit_str = rest[num_end..].trim().to_lowercase();
    let num: u64 = num_str.parse().map_err(|_| format!("'{}' is not a valid size constraint. See 'fd --help'.", s))?;
    let multiplier: u64 = match unit_str.as_str() {
        "" | "b" => 1,
        "k" => 1000,
        "m" => 1000*1000,
        "g" => 1000*1000*1000,
        "t" => 1000*1000*1000*1000,
        "ki" => 1024,
        "mi" => 1024*1024,
        "gi" => 1024*1024*1024,
        "ti" => 1024*1024*1024*1024,
        _ => {
            return Err(format!("'{}' is not a valid size constraint. See 'fd --help'.", s));
        }
    };
    let size = num * multiplier;
    Ok(SizeFilter { kind, size })
}

fn parse_time_filter(s: &str) -> Result<DateTime<Utc>, String> {
    // Try to parse as @timestamp
    if s.starts_with('@') {
        let num_str = &s[1..];
        let secs: i64 = num_str.parse().map_err(|_| format!("Invalid timestamp"))?;
        return Ok(Utc.timestamp_opt(secs, 0).unwrap());
    }
    // Try duration: 10h, 1d, 35min, 2weeks etc.
    // Units: s, sec, secs, seconds, m, min, mins, minutes, h, hour, hours, d, day, days, w, week, weeks, etc? Let's support: s, sec, m, min, h, d, day, week, weeks, month, months, year, years?
    // From fd docs: duration like 10h, 1d, 35min. Also examples 2weeks.
    // We'll implement simple parser.
    let s_lower = s.to_lowercase();
    // Check if it ends with unit
    // Try to split number and unit
    // Number may be integer? Could be float? We'll assume integer.
    // For simplicity, we will parse duration as: <num><unit> where unit in ["ns","us","ms","s","sec","secs","m","min","mins","h","hour","d","day","days","w","week","weeks","month","months","y","year","years"]
    // If parsing succeeds, compute as now - duration (for changed-within) or now - duration? Actually changed-within expects files newer than duration ago. So if argument is duration, we interpret as now - duration.
    // Similarly changed-before with duration means older than now - duration.
    // For now, if it looks like duration, we return Utc::now() - duration.

    // Try to parse as date: YYYY-MM-DD or YYYY-MM-DD HH:MM:SS
    // Also RFC3339?
    // Let's try several formats
    // First, duration detection: if contains alphabetic and not just date separators
    // We'll attempt to parse duration

    // Duration parsing
    // Regex for duration: (\d+)\s*(unit)
    // We'll try
    if let Some(caps) = regex::Regex::new(r"(?i)^\s*(\d+)\s*([a-z]+)\s*$").unwrap().captures(s) {
        let num: i64 = caps[1].parse().unwrap_or(0);
        let unit = caps[2].to_lowercase();
        let secs = match unit.as_str() {
            "s" | "sec" | "secs" | "second" | "seconds" => num,
            "m" | "min" | "mins" | "minute" | "minutes" => num * 60,
            "h" | "hour" | "hours" => num * 3600,
            "d" | "day" | "days" => num * 86400,
            "w" | "week" | "weeks" => num * 7 * 86400,
            "month" | "months" => num * 30 * 86400, // approximate
            "y" | "year" | "years" => num * 365 * 86400,
            _ => {
                // Not a duration, try date
                0
            }
        };
        if secs != 0 {
            let now = Utc::now();
            let dt = now - chrono::Duration::seconds(secs);
            return Ok(dt);
        }
    }

    // Try date only YYYY-MM-DD
    if let Ok(naive) = NaiveDateTime::parse_from_str(&format!("{} 00:00:00", s), "%Y-%m-%d %H:%M:%S") {
        let dt = Local.from_local_datetime(&naive).single().map(|d| d.with_timezone(&Utc)).unwrap_or_else(|| Utc.from_utc_datetime(&naive));
        return Ok(dt);
    }
    // Try YYYY-MM-DD HH:MM:SS
    if let Ok(naive) = NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M:%S") {
        let dt = Local.from_local_datetime(&naive).single().map(|d| d.with_timezone(&Utc)).unwrap_or_else(|| Utc.from_utc_datetime(&naive));
        return Ok(dt);
    }
    // Try RFC3339
    if let Ok(dt) = DateTime::parse_from_rfc3339(s) {
        return Ok(dt.with_timezone(&Utc));
    }
    // Try @timestamp already handled
    // Try as datetime with T separator?
    if let Ok(dt) = s.parse::<DateTime<Utc>>() {
        return Ok(dt);
    }
    Err(format!("Unable to parse date/duration: {}", s))
}

