    let text_exts = ["txt","md","rst","csv"];
    let doc_exts = ["doc","docx","xls","xlsx","ppt","pptx"];
    let config_exts = ["json","toml","yaml","yml","ini","conf","cfg","cnf"];

    // Check for executable already handled
    // Check archive
    if archive_exts.contains(&ext.as_str()) || path_str.ends_with(".tar.gz") || path_str.ends_with(".tar.bz2") {
        return format!("\x1b[4;38;5;203m{}\x1b[0m", display);
    }
    // .o
    if ext == "o" {
        return format!("\x1b[38;5;243m{}\x1b[0m", display);
    }
    if media_exts.contains(&ext.as_str()) {
        return format!("\x1b[38;5;208m{}\x1b[0m", display);
    }
    if source_exts.contains(&ext.as_str()) {
        return format!("\x1b[38;5;48m{}\x1b[0m", display);
    }
    if text_exts.contains(&ext.as_str()) {
        return format!("\x1b[38;5;185m{}\x1b[0m", display);
    }
    if doc_exts.contains(&ext.as_str()) {
        return format!("\x1b[38;5;186m{}\x1b[0m", display);
    }
    if config_exts.contains(&ext.as_str()) {
        return format!("\x1b[38;5;149m{}\x1b[0m", display);
    }
    // Check for Makefile without extension
    let file_name = Path::new(&path_str).file_name().and_then(|n| n.to_str()).unwrap_or("").to_lowercase();
    if file_name == "makefile" || file_name == "gnumakefile" || file_name == "cmakelists.txt" {
        return format!("\x1b[38;5;149m{}\x1b[0m", display);
    }

