                } else if source_exts.contains(&file_ext.as_str()) {
                    format!("\x1b[38;5;48m{}\x1b[0m", file_part)
                } else if text_exts.contains(&file_ext.as_str()) {
                    format!("\x1b[38;5;185m{}\x1b[0m", file_part)
                } else if doc_exts.contains(&file_ext.as_str()) {
                    format!("\x1b[38;5;186m{}\x1b[0m", file_part)
                } else if config_exts.contains(&file_ext.as_str()) {
                    format!("\x1b[38;5;149m{}\x1b[0m", file_part)
