fn parse_file_type(s: &str) -> Option<FileTypeFilter> {
    match s.to_lowercase().as_str() {
        "f" | "file" => Some(FileTypeFilter::File),
        "d" | "dir" | "directory" => Some(FileTypeFilter::Directory),
