fn parse_time_filter(s: &str) -> Result<DateTime<Utc>, String> {
    if s.starts_with('@') {
        let num_str = &s[1..];
        let secs: i64 = num_str.parse().map_err(|_| format!("Invalid timestamp"))?;
        return Ok(Utc.timestamp_opt(secs, 0).unwrap());
    }
    if let Some(caps) = Regex::new(r"(?i)^\s*(\d+)\s*([a-z]+)\s*$").unwrap().captures(s) {
        let num: i64 = caps[1].parse().unwrap_or(0);
        let unit = caps[2].to_lowercase();
        let secs = match unit.as_str() {
            "s" | "sec" | "secs" | "second" | "seconds" => num,
            "m" | "min" | "mins" | "minute" | "minutes" => num * 60,
            "h" | "hour" | "hours" => num * 3600,
            "d" | "day" | "days" => num * 86400,
            "w" | "week" | "weeks" => num * 7 * 86400,
            "month" | "months" => num * 30 * 86400,
            "y" | "year" | "years" => num * 365 * 86400,
            _ => 0
        };
        if secs != 0 {
            let now = Utc::now();
            return Ok(now - chrono::Duration::seconds(secs));
        }
    }
    if let Ok(naive) = NaiveDateTime::parse_from_str(&format!("{} 00:00:00", s), "%Y-%m-%d %H:%M:%S") {
        let dt = Local.from_local_datetime(&naive).single().map(|d| d.with_timezone(&Utc)).unwrap_or_else(|| Utc.from_utc_datetime(&naive));
        return Ok(dt);
    }
    if let Ok(naive) = NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M:%S") {
        let dt = Local.from_local_datetime(&naive).single().map(|d| d.with_timezone(&Utc)).unwrap_or_else(|| Utc.from_utc_datetime(&naive));
        return Ok(dt);
    }
    if let Ok(dt) = DateTime::parse_from_rfc3339(s) { return Ok(dt.with_timezone(&Utc)); }
    if let Ok(dt) = s.parse::<DateTime<Utc>>() { return Ok(dt); }
    Err(format!("Unable to parse date/duration: {}", s))
}
#[derive(Debug)] struct OwnerFilter { uid: Option<(u32,bool)>, gid: Option<(u32,bool)>, user_name: Option<(String,bool)>, group_name: Option<(String,bool)>, }
fn get_uid_by_name(name: &str) -> Option<u32> {
    if let Ok(content) = fs::read_to_string("/etc/passwd") {
        for line in content.lines() {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len()>=3 && parts[0]==name { if let Ok(uid)=parts[2].parse::<u32>() { return Some(uid); } }
        }
    }
    None
}
fn get_gid_by_name(name: &str) -> Option<u32> {
    if let Ok(content) = fs::read_to_string("/etc/group") {
        for line in content.lines() {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len()>=3 && parts[0]==name { if let Ok(gid)=parts[2].parse::<u32>() { return Some(gid); } }
        }
    }
    None
}
fn parse_owner(s: &str) -> Result<OwnerFilter, String> {
    let mut filter = OwnerFilter { uid: None, gid: None, user_name: None, group_name: None };
    if s.contains(':') {
        let parts: Vec<&str> = s.splitn(2, ':').collect();
        let user_part = parts[0]; let group_part = parts[1];
        if !user_part.is_empty() {
            let (neg, name) = if user_part.starts_with('!') { (true, &user_part[1..]) } else { (false, user_part) };
            if name.is_empty() { return Err(format!("'' is not a recognized user name")); }
            if let Ok(uid)=name.parse::<u32>() { filter.uid=Some((uid,neg)); } else { filter.user_name=Some((name.to_string(),neg)); }
        }
        if !group_part.is_empty() {
            let (neg, name) = if group_part.starts_with('!') { (true, &group_part[1..]) } else { (false, group_part) };
            if name.is_empty() { return Err(format!("'' is not a recognized group name")); }
            if let Ok(gid)=name.parse::<u32>() { filter.gid=Some((gid,neg)); } else { filter.group_name=Some((name.to_string(),neg)); }
        }
    } else {
        let (neg, name) = if s.starts_with('!') { (true, &s[1..]) } else { (false, s) };
        if name.is_empty() { return Err(format!("'' is not a recognized user name")); }
        if let Ok(uid)=name.parse::<u32>() { filter.uid=Some((uid,neg)); } else { filter.user_name=Some((name.to_string(),neg)); }
    }
    Ok(filter)
}
fn check_owner(meta: &fs::Metadata, filter: &OwnerFilter) -> bool {
    let uid = meta.uid(); let gid = meta.gid();
    let uid_match = if let Some((filter_uid, neg)) = filter.uid {
        let m = uid == filter_uid; if neg { !m } else { m }
    } else if let Some((ref name, neg)) = filter.user_name {
        if let Some(filter_uid)=get_uid_by_name(name) { let m = uid == filter_uid; if neg { !m } else { m } } else { if neg { true } else { false } }
    } else { true };
    let gid_match = if let Some((filter_gid, neg)) = filter.gid {
        let m = gid == filter_gid; if neg { !m } else { m }
    } else if let Some((ref name, neg)) = filter.group_name {
        if let Some(filter_gid)=get_gid_by_name(name) { let m = gid == filter_gid; if neg { !m } else { m } } else { if neg { true } else { false } }
    } else { true };
    uid_match && gid_match
}

