    if doc_exts.contains(&ext.as_str()) { return format!("\x1b[38;5;186m{}\x1b[0m", display); }
    if config_exts.contains(&ext.as_str()) { return format!("\x1b[38;5;149m{}\x1b[0m", display); }
    let file_name = Path::new(&path_str).file_name().and_then(|n| n.to_str()).unwrap_or("").to_lowercase();
    if file_name=="makefile" || file_name=="gnumakefile" || file_name=="cmakelists.txt" { return format!("\x1b[38;5;149m{}\x1b[0m", display); }
    if display.contains('/') {
        if let Some(last_slash) = display.rfind('/') {
