    } else if let Some((ref name, neg)) = filter.group_name {
        if let Some(filter_gid)=get_gid_by_name(name) { let m = gid == filter_gid; if neg { !m } else { m } } else { if neg { true } else { false } }
    } else { true };
    uid_match && gid_match
}

fn main() {
    let mut cmd = Command::new("fd").version("10.3.0").about("A program to find entries in your filesystem")
        .arg(Arg::new("pattern").required(false))
        .arg(Arg::new("path").num_args(0..))
