        .arg(Arg::new("one-file-system").long("one-file-system").action(ArgAction::SetTrue))
        ;

    let matches = cmd.get_matches();

    let search_paths: Vec<String> = matches.get_many::<String>("search-path").map(|v| v.cloned().collect()).unwrap_or_default();
    let use_search_path = !search_paths.is_empty();
    let positional_pattern = matches.get_one::<String>("pattern").map(|s| s.clone());
    let positional_paths: Vec<String> = matches.get_many::<String>("path").map(|v| v.cloned().collect()).unwrap_or_default();

    let (pattern_opt, roots) : (Option<String>, Vec<String>) = if use_search_path {
        if !positional_paths.is_empty() {
            eprintln!("error: the argument '--search-path <search-path>' cannot be used with '[path]...'");
            eprintln!("\nUsage: executable --search-path <search-path> <pattern> [path]...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        (positional_pattern.clone(), search_paths.clone())
    } else {
        (positional_pattern.clone(), positional_paths.clone())
    };

    if let Some(_) = matches.get_one::<String>("strip-cwd-prefix") {
        if use_search_path {
            eprintln!("error: the argument '--search-path <search-path>' cannot be used with '--strip-cwd-prefix[=<when>]'");
            eprintln!("\nUsage: executable --search-path <search-path> <pattern> [path]...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        if !roots.is_empty() {
            eprintln!("error: the argument '--strip-cwd-prefix[=<when>]' cannot be used with '[path]...'");
            eprintln!("\nUsage: executable <pattern> <path>...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }

    if let Some(ref pat) = pattern_opt {
        if pat.contains('/') && !matches.get_flag("full-path") && !pat.is_empty() {
            eprintln!("[fd error]: The search pattern '{}' contains a path-separation character ('/') and will not lead to any search results.", pat);
            eprintln!();
            eprintln!("If you want to search for all files inside the '{}' directory, use a match-all pattern:", pat);
            eprintln!();
            eprintln!("  fd . '{}'", pat);
            eprintln!();
            eprintln!("Instead, if you want your pattern to match the full file path, use:");
            eprintln!();
            eprintln!("  fd --full-path '{}'", pat);
            std::process::exit(1);
        }
    }

    if matches.get_flag("fixed-strings") && matches.get_flag("glob") {
        eprintln!("error: the argument '--fixed-strings' cannot be used with '--glob'");
        eprintln!("\nUsage: executable --fixed-strings <pattern> [path]...\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    if matches.get_flag("absolute-path") && matches.get_flag("list-details") {
        eprintln!("error: the argument '--absolute-path' cannot be used with '--list-details'");
        eprintln!("\nUsage: executable --absolute-path [pattern] [path]...\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    if matches.get_flag("relative-path") && matches.get_flag("list-details") {
        eprintln!("error: the argument '--relative-path' cannot be used with '--list-details'");
        eprintln!("\nUsage: executable --relative-path [pattern] [path]...\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }

    let base_dir_opt = matches.get_one::<String>("base-directory").map(|s| PathBuf::from(s));
    if let Some(ref base) = base_dir_opt {
        if let Err(_) = std::env::set_current_dir(base) {
            eprintln!("[fd error]: Base directory '{}' is not a directory.", base.display());
            std::process::exit(1);
        }
    }

    let search_roots_final: Vec<PathBuf> = if roots.is_empty() { vec![PathBuf::from(".")] } else { roots.iter().map(|s| PathBuf::from(s)).collect() };
    let mut valid_roots: Vec<PathBuf> = Vec::new();
    let mut has_error = false;
    for root in &search_roots_final {
        match fs::metadata(root) {
            Ok(meta) => { if !meta.is_dir() { eprintln!("[fd error]: Search path '{}' is not a directory.", root.display()); has_error=true; } else { valid_roots.push(root.clone()); } },
            Err(_) => { eprintln!("[fd error]: Search path '{}' is not a directory.", root.display()); has_error=true; }
        }
    }
    if has_error && valid_roots.is_empty() { eprintln!("[fd error]: No valid search paths given."); std::process::exit(1); }

    let pattern_str = pattern_opt.clone().unwrap_or_default();
    let glob_flag = matches.get_flag("glob");
    let fixed_flag = matches.get_flag("fixed-strings");
    let case_sensitive_flag = matches.get_flag("case-sensitive");
    let ignore_case_flag = matches.get_flag("ignore-case");
    let is_case_sensitive = if case_sensitive_flag { true } else if ignore_case_flag { false } else { pattern_str.chars().any(|c| c.is_uppercase()) };
    let and_patterns: Vec<String> = matches.get_many::<String>("and").map(|v| v.cloned().collect()).unwrap_or_default();
    let main_regex_opt: Option<Regex> = if pattern_str.is_empty() { None } else {
        if fixed_flag {
            let escaped = regex::escape(&pattern_str);
            let re_str = if is_case_sensitive { escaped } else { format!("(?i){}", escaped) };
            match Regex::new(&re_str) { Ok(r)=>Some(r), Err(e)=>{ eprintln!("[fd error]: {}", e); std::process::exit(1); } }
        } else if glob_flag { None } else {
            let re_str = if is_case_sensitive { pattern_str.clone() } else { format!("(?i){}", pattern_str) };
            match Regex::new(&re_str) { Ok(r)=>Some(r), Err(e)=>{ eprintln!("[fd error]: {}", e); std::process::exit(1); } }
        }
    };
    let mut and_regexes: Vec<Regex> = Vec::new();
    let mut and_globs: Vec<GlobSet> = Vec::new();
    for and_pat in &and_patterns {
        let and_case_sensitive = if case_sensitive_flag { true } else if ignore_case_flag { false } else { and_pat.chars().any(|c| c.is_uppercase()) };
        if fixed_flag {
            let escaped = regex::escape(and_pat);
            let re_str = if and_case_sensitive { escaped } else { format!("(?i){}", escaped) };
            match Regex::new(&re_str) { Ok(r)=>and_regexes.push(r), Err(e)=>{ eprintln!("[fd error]: {}", e); std::process::exit(1); } }
        } else if glob_flag {
            let mut builder = GlobSetBuilder::new();
            let glob = Glob::new(and_pat).unwrap_or_else(|e| { eprintln!("[fd error]: {}", e); std::process::exit(1); });
            builder.add(glob);
            and_globs.push(builder.build().unwrap());
        } else {
            let re_str = if and_case_sensitive { and_pat.clone() } else { format!("(?i){}", and_pat) };
            match Regex::new(&re_str) { Ok(r)=>and_regexes.push(r), Err(e)=>{ eprintln!("[fd error]: {}", e); std::process::exit(1); } }
        }
    }
    let main_globset_opt: Option<GlobSet> = if glob_flag && !pattern_str.is_empty() {
        let mut builder = GlobSetBuilder::new();
        match Glob::new(&pattern_str) {
            Ok(g) => { builder.add(g); match builder.build() { Ok(set)=>Some(set), Err(e)=>{ eprintln!("[fd error]: {}", e); std::process::exit(1); } } },
            Err(e) => { eprintln!("[fd error]: {}", e); std::process::exit(1); }
        }
    } else { None };
    let hidden = matches.get_flag("hidden") || matches.get_count("unrestricted") > 0;
    let no_ignore = matches.get_flag("no-ignore") || matches.get_count("unrestricted") > 0;
    let no_ignore_vcs = matches.get_flag("no-ignore-vcs") || matches.get_flag("no-ignore");
    let no_require_git = matches.get_flag("no-require-git");
    let require_git = matches.get_flag("require-git");
    let no_ignore_parent = matches.get_flag("no-ignore-parent");
    let ignore_contain: Vec<String> = matches.get_many::<String>("ignore-contain").map(|v| v.cloned().collect()).unwrap_or_default();
    let max_depth = if let Some(d) = matches.get_one::<usize>("max-depth") { Some(*d) } else if let Some(d) = matches.get_one::<usize>("exact-depth") { Some(*d) } else { None };
    let min_depth = if let Some(d) = matches.get_one::<usize>("min-depth") { Some(*d) } else if let Some(d) = matches.get_one::<usize>("exact-depth") { Some(*d) } else { None };
    let type_filters_raw: Vec<String> = matches.get_many::<String>("type").map(|v| v.cloned().collect()).unwrap_or_default();
    let mut type_filters: Vec<FileTypeFilter> = Vec::new();
    for t in type_filters_raw {
        if let Some(f) = parse_file_type(&t) { type_filters.push(f); } else {
            eprintln!("error: invalid value '{}' for '--type <filetype>'", t);
            eprintln!("  [possible values: file, directory, symlink, block-device, char-device, executable, empty, socket, pipe]");
            eprintln!("\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }
    let ext_filters_raw: Vec<String> = matches.get_many::<String>("extension").map(|v| v.cloned().collect()).unwrap_or_default();
    let mut ext_filters: Vec<String> = Vec::new();
    for e in ext_filters_raw {
        let mut ext = e;
        if ext.starts_with('.') { ext = ext[1..].to_string(); }
        ext_filters.push(ext.to_lowercase());
    }
    let exclude_patterns_raw: Vec<String> = matches.get_many::<String>("exclude").map(|v| v.cloned().collect()).unwrap_or_default();
    let mut exclude_globset: Option<GlobSet> = None;
    if !exclude_patterns_raw.is_empty() {
        let mut builder = GlobSetBuilder::new();
        for pat in &exclude_patterns_raw {
            let glob = Glob::new(pat).unwrap_or_else(|e| { eprintln!("[fd error]: {}", e); std::process::exit(1); });
            builder.add(glob);
        }
        exclude_globset = Some(builder.build().unwrap());
    }
    let size_filters_raw: Vec<String> = matches.get_many::<String>("size").map(|v| v.cloned().collect()).unwrap_or_default();
    let mut size_filters: Vec<SizeFilter> = Vec::new();
    for s in size_filters_raw {
        match parse_size(&s) {
            Ok(f) => size_filters.push(f),
            Err(e) => {
                eprintln!("error: invalid value '{}' for '--size <size>': {}", s, e);
                eprintln!("\nFor more information, try '--help'.");
                std::process::exit(2);
            }
        }
    }
    let changed_within_raw = matches.get_one::<String>("changed-within").map(|s| s.clone());
    let changed_before_raw = matches.get_one::<String>("changed-before").map(|s| s.clone());
    let changed_within_dt: Option<DateTime<Utc>> = if let Some(ref s) = changed_within_raw {
        match parse_time_filter(s) { Ok(dt) => Some(dt), Err(e) => { eprintln!("[fd error]: {}", e); std::process::exit(1); } }
    } else { None };
    let changed_before_dt: Option<DateTime<Utc>> = if let Some(ref s) = changed_before_raw {
        match parse_time_filter(s) { Ok(dt) => Some(dt), Err(e) => { eprintln!("[fd error]: {}", e); std::process::exit(1); } }
    } else { None };
    let owner_raw = matches.get_one::<String>("owner").map(|s| s.clone());
    let owner_filter: Option<OwnerFilter> = if let Some(ref s) = owner_raw {
        match parse_owner(s) {
            Ok(f) => Some(f),
            Err(e) => {
                eprintln!("error: invalid value '{}' for '--owner <user:group>': {}", s, e);
                eprintln!("\nFor more information, try '--help'.");
                std::process::exit(2);
            }
        }
    } else { None };
    let color_when = matches.get_one::<String>("color").unwrap().clone();
    let hyperlink_when = matches.get_one::<String>("hyperlink").unwrap().clone();
    let print0 = matches.get_flag("print0");
    let absolute_path = matches.get_flag("absolute-path");
    let relative_path = matches.get_flag("relative-path");
    let is_absolute = if relative_path { false } else if absolute_path { true } else { false };
    let path_sep = matches.get_one::<String>("path-separator").map(|s| s.clone()).unwrap_or_else(|| std::path::MAIN_SEPARATOR.to_string());
    let format_opt = matches.get_one::<String>("format").map(|s| s.clone());
    let list_details = matches.get_flag("list-details");
    let follow = matches.get_flag("follow");
    let prune = matches.get_flag("prune");
    let one_file_system = matches.get_flag("one-file-system");
    let show_errors = matches.get_flag("show-errors");
    let max_results_opt = if matches.get_flag("1") { Some(1) } else { matches.get_one::<usize>("max-results").cloned() };
    let quiet = matches.get_flag("quiet");
    let ignore_file_opt = matches.get_one::<String>("ignore-file").map(|s| s.clone());
    let use_color = match color_when.as_str() { "always"=>true, "never"=>false, "auto"=>false, _=>false };
    let use_hyperlink = match hyperlink_when.as_str() { "always"=>true, "never"=>false, "auto"=>use_color, _=>false };
    let mut results: Vec<PathBuf> = Vec::new();
    let mut pruned_dirs: Vec<PathBuf> = Vec::new();
    for root in &valid_roots {
        let mut builder = WalkBuilder::new(root);
        builder.hidden(!hidden);
        if no_ignore {
            builder.ignore(false); builder.git_ignore(false); builder.git_global(false); builder.git_exclude(false); builder.require_git(false);
        } else if no_ignore_vcs {
            builder.git_ignore(false); builder.git_global(false); builder.git_exclude(false); builder.ignore(true);
        } else {
            builder.ignore(true); builder.git_ignore(true); builder.git_global(true); builder.git_exclude(true);
            if no_require_git { builder.require_git(false); } else if require_git { builder.require_git(true); } else { builder.require_git(true); }
        }
        if no_ignore_parent { builder.parents(false); } else { builder.parents(true); }
        builder.follow_links(follow);
        if let Some(md) = max_depth { builder.max_depth(Some(md)); }
        if let Some(ref ignore_file) = ignore_file_opt { builder.add_ignore(Path::new(ignore_file)); }
        if one_file_system { builder.same_file_system(true); }
        if let Some(threads) = matches.get_one::<usize>("threads") { builder.threads(*threads); }
        let walker = builder.build();
        for entry in walker {
            let entry = match entry {
                Ok(e) => e,
                Err(err) => { if show_errors { eprintln!("[fd error]: {}", err); } continue; }
            };
            let path = entry.path().to_path_buf();
            let depth = entry.depth();
            if depth==0 { continue; }
            if let Some(min_d) = min_depth { if depth < min_d { continue; } }
            if prune {
                let mut skip = false;
                for pd in &pruned_dirs { if path.starts_with(pd) && path != *pd { skip=true; break; } }
                if skip { continue; }
            }
            let mut should_ignore_contain = false;
            if !ignore_contain.is_empty() {
                for anc in path.ancestors().skip(1) {
                    for ic_name in &ignore_contain {
                        let candidate = anc.join(ic_name);
                        if candidate.exists() { should_ignore_contain=true; break; }
                    }
                    if should_ignore_contain { break; }
                }
                if !should_ignore_contain && path.is_dir() {
                    for ic_name in &ignore_contain { if path.join(ic_name).exists() { should_ignore_contain=true; break; } }
                }
            }
            if should_ignore_contain { continue; }
            if let Some(ref excl_set) = exclude_globset {
                let file_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
                let path_str = path.to_string_lossy();
                let mut is_excluded = false;
                if excl_set.is_match(file_name) || excl_set.is_match(path_str.as_ref()) { is_excluded=true; }
                if !is_excluded {
                    for anc in path.ancestors().skip(1) {
                        if let Some(fname) = anc.file_name().and_then(|n| n.to_str()) { if excl_set.is_match(fname) { is_excluded=true; break; } }
                        if excl_set.is_match(anc.to_string_lossy().as_ref()) { is_excluded=true; break; }
                    }
                }
                if is_excluded { continue; }
            }
            let meta = match fs::symlink_metadata(&path) { Ok(m)=>m, Err(_)=>{ continue; } };
            if !type_filters.is_empty() {
                let mut type_match = false;
                for tf in &type_filters {
                    match tf {
                        FileTypeFilter::File => { if meta.is_file() { type_match=true; } },
                        FileTypeFilter::Directory => { if meta.is_dir() { type_match=true; } },
                        FileTypeFilter::Symlink => { if meta.file_type().is_symlink() { type_match=true; } },
                        FileTypeFilter::Executable => { if meta.is_file() { let mode=meta.mode(); if mode & 0o111 !=0 { type_match=true; } } },
                        FileTypeFilter::Empty => {
                            if meta.is_file() { if meta.len()==0 { type_match=true; } }
                            else if meta.is_dir() { if let Ok(rd)=fs::read_dir(&path) { if rd.count()==0 { type_match=true; } } }
                        },
                        FileTypeFilter::Socket => { let mode=meta.mode(); if mode & 0o170000 == 0o140000 { type_match=true; } },
                        FileTypeFilter::Pipe => { let mode=meta.mode(); if mode & 0o170000 == 0o10000 { type_match=true; } },
                        FileTypeFilter::BlockDevice => { let mode=meta.mode(); if mode & 0o170000 == 0o60000 { type_match=true; } },
                        FileTypeFilter::CharDevice => { let mode=meta.mode(); if mode & 0o170000 == 0o20000 { type_match=true; } },
                    }
                }
                if !type_match { continue; }
            }
            if !ext_filters.is_empty() {
                if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
                    let ext_lower = ext.to_lowercase();
                    if !ext_filters.contains(&ext_lower) { continue; }
                } else { continue; }
            }
            if !size_filters.is_empty() {
                if !meta.is_file() { continue; }
                let file_size = meta.len();
                let mut size_ok = true;
                for sf in &size_filters {
                    match sf.kind {
                        '+' => { if file_size < sf.size { size_ok=false; break; } },
                        '-' => { if file_size > sf.size { size_ok=false; break; } },
                        '=' => { if file_size != sf.size { size_ok=false; break; } },
                        _ => {}
                    }
                }
                if !size_ok { continue; }
            }
            if let Some(ref within_dt) = changed_within_dt {
                let mtime = meta.mtime() as i64;
                let mtime_dt = Utc.timestamp_opt(mtime, 0).unwrap();
                if mtime_dt < *within_dt { continue; }
            }
            if let Some(ref before_dt) = changed_before_dt {
                let mtime = meta.mtime() as i64;
                let mtime_dt = Utc.timestamp_opt(mtime, 0).unwrap();
                if mtime_dt > *before_dt { continue; }
            }
            if let Some(ref of) = owner_filter { if !check_owner(&meta, of) { continue; } }
            let match_target = if matches.get_flag("full-path") {
