fn get_hostname() -> String {
    if let Ok(content) = fs::read_to_string("/etc/hostname") { return content.trim().to_string(); }
    if let Ok(content) = fs::read_to_string("/proc/sys/kernel/hostname") { return content.trim().to_string(); }
    if let Ok(h) = std::env::var("HOSTNAME") { return h; }
    "localhost".to_string()
