                // For simplicity, we will split correctly:
                let mut colored = String::new();
                let mut remaining = display;
                while let Some(idx) = remaining.find('/') {
                    let (dir_part, rest) = remaining.split_at(idx);
                    // dir_part is component
                    if !dir_part.is_empty() {
                        colored.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", dir_part));
                    }
                    colored.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", "/"));
                    remaining = &rest[1..];
                }
                if !remaining.is_empty() {
                    colored.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", remaining));
                }
                return colored;
            } else {
                return format!("\x1b[38;5;81m{}\x1b[0m", display);
            }
        }
        if m.is_file() {
            let mode=m.mode();
            if mode & 0o111 !=0 {
                // executable: need to check if display has dir part?
                if display.contains('/') {
                    // split dir and file
                    if let Some(idx) = display.rfind('/') {
                        let dir_part = &display[..=idx];
                        let file_part = &display[idx+1..];
                        if file_part.is_empty() {
                            return format!("\x1b[38;5;81m{}\x1b[0m", display);
                        } else {
                            // dir part colored as dir, file as executable
                            let dir_colored = {
                                // color each dir component
                                let mut colored_dir = String::new();
                                let mut rem = dir_part;
                                while let Some(slash_idx) = rem.find('/') {
                                    let (comp, rest) = rem.split_at(slash_idx);
                                    if !comp.is_empty() {
                                        colored_dir.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", comp));
                                    }
                                    colored_dir.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", "/"));
                                    rem = &rest[1..];
                                }
                                if !rem.is_empty() {
                                    colored_dir.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", rem));
                                }
                                colored_dir
                            };
                            return format!("{}{}", dir_colored, format!("\x1b[1;38;5;203m{}\x1b[0m", file_part));
                        }
                    }
                }
                return format!("\x1b[1;38;5;203m{}\x1b[0m", display);
            }
        }
        let mode=m.mode();
        if mode & 0o170000 == 0o10000 {
            return format!("\x1b[48;5;81;38;5;16m{}\x1b[0m", display);
        }
    }
