        .arg(Arg::new("one-file-system").long("one-file-system").action(ArgAction::SetTrue))
        ;

    let matches = cmd.get_matches();

    // Check for exec parsing manually from raw_args to handle ';'
    // We need to extract all --exec and --exec-batch commands with ';' separator
    let mut exec_commands: Vec<Vec<String>> = Vec::new();
    let mut exec_batch_commands: Vec<Vec<String>> = Vec::new();
    let mut i = 0;
    while i < raw_args.len() {
        let arg = &raw_args[i];
        if arg == "-x" || arg == "--exec" {
            i+=1;
            let mut cmd_args: Vec<String> = Vec::new();
            while i < raw_args.len() {
                let a = &raw_args[i];
                if a == ";" {
                    i+=1;
                    break;
                }
                // If a looks like a flag that is not part of command? But fd says all subsequent positional arguments are considered to be arguments to the command unless ';' ends list.
                // For simplicity, we stop when we encounter a flag that is known fd flag and we are at start? Actually we need more robust.
                // We will check if a starts with '-' and is a known fd flag, then we treat it as end of exec args and continue parsing as fd options? But fd documentation says it's recommended to place -x last. Alternatively you can supply ';' to end list and continue with more fd options.
                // So if we encounter ';', we end. If we encounter another -x or -X, we end? Actually multiple exec commands can be specified, each terminated by ';' except last.
                // So we need to detect when arg is -x or -X or other fd options? For simplicity, we will treat ';' as terminator, otherwise if we see -x or -X we treat as new exec command start (so previous command ends)
                if a == "-x" || a == "--exec" || a == "-X" || a == "--exec-batch" {
                    break;
                }
                // Also if a is a known flag like --hidden, -H, etc, and cmd_args not empty, should we treat as end? In fd, after -x, all subsequent positional arguments are considered to be arguments to the command, not to fd. So flags after -x should be considered part of command unless ';' used.
                // Therefore, we should NOT stop on flags; we should consume all remaining args as command args until ';' or end or next -x/-X?
                // But original fd's clap parsing handles --exec as taking all following args as command unless ';'.
                // For our manual parsing, we will just consume until we encounter ';' or next -x/-X that is at beginning of a new exec.
                // Also need to handle that -x may appear multiple times: we should collect each command separately.

                cmd_args.push(a.clone());
                i+=1;
            }
            if !cmd_args.is_empty() {
                exec_commands.push(cmd_args);
            }
            continue;
        } else if arg == "-X" || arg == "--exec-batch" {
            i+=1;
            let mut cmd_args: Vec<String> = Vec::new();
            while i < raw_args.len() {
                let a = &raw_args[i];
                if a == ";" {
                    i+=1;
                    break;
                }
                if a == "-x" || a == "--exec" || a == "-X" || a == "--exec-batch" {
                    break;
                }
                cmd_args.push(a.clone());
                i+=1;
            }
