                // Parse batch command: check placeholders
                // We'll need to handle batch-size splitting

                let has_placeholder = batch_cmd_template.iter().any(|arg| arg.contains("{}") || arg.contains("{/}") || arg.contains("{//}") || arg.contains("{.}") || arg.contains("{/.}"));

                // Prepare placeholder detection
                // For batch, we need to expand each arg containing placeholder into multiple args (one per result)

                // If no placeholder, implicit {} at end

                let mut cmd_template = batch_cmd_template.clone();
                if !has_placeholder {
                    cmd_template.push("{}".to_string());
                }

                // Check for multiple placeholders types?
                // Let's count distinct placeholder kinds used
                let mut placeholder_kinds: std::collections::HashSet<String> = std::collections::HashSet::new();
                for arg in &cmd_template {
                    if arg.contains("{}") { placeholder_kinds.insert("{}".to_string()); }
                    if arg.contains("{/}") { placeholder_kinds.insert("{/}".to_string()); }
                    if arg.contains("{//}") { placeholder_kinds.insert("{//}".to_string()); }
                    if arg.contains("{.}") { placeholder_kinds.insert("{.}".to_string()); }
                    if arg.contains("{/.}") { placeholder_kinds.insert("{/.}".to_string()); }
                }
                if placeholder_kinds.len() > 1 {
                    eprintln!("error: Only one placeholder allowed for batch commands");
                    eprintln!("\nUsage: fd [OPTIONS] [pattern] [path]...\n\nFor more information, try '--help'.");
                    std::process::exit(2);
                }

                // Now batch execution with batch_size
                // If batch_size 0, all results in one batch
                // Else split

                let batches: Vec<Vec<PathBuf>> = if batch_size_val == 0 {
                    vec![results.clone()]
                } else {
                    let mut b: Vec<Vec<PathBuf>> = Vec::new();
                    let mut current: Vec<PathBuf> = Vec::new();
                    for r in &results {
                        current.push(r.clone());
                        if current.len() >= batch_size_val {
                            b.push(current.clone());
                            current.clear();
                        }
                    }
                    if !current.is_empty() { b.push(current); }
                    b
                };

                for batch in batches {
                    let mut exec_args: Vec<String> = Vec::new();
                    for template_arg in &cmd_template {
                        if template_arg.contains("{}") || template_arg.contains("{/}") || template_arg.contains("{//}") || template_arg.contains("{.}") || template_arg.contains("{/.}") {
                            // Expand for each file in batch
                            for res_path in &batch {
                                let expanded = expand_placeholder(template_arg, res_path, &path_sep, is_absolute, strip_for_exec);
                                exec_args.push(expanded);
                            }
                        } else {
                            // Keep arg but also expand escaped braces?
                            let expanded = expand_placeholder(template_arg, &PathBuf::from(""), &path_sep, is_absolute, strip_for_exec);
                            // Actually for non-placeholder args, we still need to handle {{ and }} escaping
                            let esc = template_arg.replace("{{", "{").replace("}}", "}");
                            exec_args.push(esc);
                        }
                    }

                    // exec_args[0] is command
                    if exec_args.is_empty() { continue; }
                    let cmd_name = exec_args[0].clone();
                    let cmd_args = &exec_args[1..];
                    let mut child = process::Command::new(cmd_name).args(cmd_args).spawn().unwrap_or_else(|e| { eprintln!("Failed to execute: {}", e); std::process::exit(1); });
                    let _ = child.wait();
                }
            }
        }

        if !exec_commands.is_empty() {
            // For each result, for each exec command
            // Use rayon for parallel? We'll use sequential for simplicity but we can attempt parallel with std threads

            // For print0 with exec, we need to print null between outputs
            // According to fd docs: If --print0 is also given, then a null character will be printed between the output for each found entry.

            // Actually exec's output is from the command, not fd's path. So fd should print command's output and then maybe null separator?

            // From earlier test: fd -0 txt -x echo "foo" gave output like "foo ./base/dir/file.txt\n\0foo ./a/file1.txt\n\0..."
            // So fd runs command for each file, and after each command's output, it prints null if print0 enabled? Or the command's output itself is printed, and fd adds null between? Let's see raw: earlier we had print0 exec raw b'foo ./base/dir/file.txt\n\x00foo ./a/file1.txt\n\x00...'
            // That suggests command was echo foo <path>, so output "foo <path>\n", then null, then next.

            // For implementation, we will for each result, for each exec command, run command and capture? Actually fd runs command and lets its stdout go to fd's stdout directly, not captured. So null separator is printed by fd after each command's execution? Let's see: if command prints "foo <path>\n", and fd prints null after, we get "foo <path>\n\0"

            // So we should after each exec command execution, if print0, print null char to stdout.

            for res_path in &results {
                for exec_cmd_template in &exec_commands {
                    let has_placeholder = exec_cmd_template.iter().any(|arg| arg.contains("{}") || arg.contains("{/}") || arg.contains("{//}") || arg.contains("{.}") || arg.contains("{/.}"));
                    let mut cmd_template = exec_cmd_template.clone();
                    if !has_placeholder {
                        cmd_template.push("{}".to_string());
                    }

                    let mut exec_args: Vec<String> = Vec::new();
                    for template_arg in &cmd_template {
                        let expanded = expand_placeholder(template_arg, res_path, &path_sep, is_absolute, strip_for_exec);
                        exec_args.push(expanded);
                    }

                    if exec_args.is_empty() { continue; }
                    let cmd_name = exec_args[0].clone();
                    let cmd_args = &exec_args[1..];
                    let mut child = process::Command::new(cmd_name).args(cmd_args).spawn().unwrap_or_else(|e| { eprintln!("Failed to execute: {}", e); std::process::exit(1); });
                    let _ = child.wait();
                    if use_null_sep {
                        print!("\0");
                        // flush?
                        use std::io::Write;
                        std::io::stdout().flush().unwrap();
                    }
                }
            }
        }

        return;
    }

    if list_details {
        let mut sorted = results.clone(); sorted.sort();
        let mut cmd_ls = std::process::Command::new("ls");
        cmd_ls.arg("-l"); cmd_ls.arg("-d");
        for p in &sorted {
            let mut out_path = if is_absolute {
                match p.canonicalize() { Ok(pp)=>pp.to_string_lossy().to_string(), Err(_)=>p.to_string_lossy().to_string() }
            } else {
                let s = p.to_string_lossy().to_string();
                if s.starts_with("./") { s } else { format!("./{}", s) }
            };
            if path_sep != std::path::MAIN_SEPARATOR.to_string() { out_path = out_path.replace(std::path::MAIN_SEPARATOR, &path_sep); }
            cmd_ls.arg(out_path);
        }
        let output = cmd_ls.output().expect("failed to execute ls");
        print!("{}", String::from_utf8_lossy(&output.stdout));
        if !output.stderr.is_empty() { eprint!("{}", String::from_utf8_lossy(&output.stderr)); }
        return;
    }

    let strip_cwd_prefix_opt = matches.get_one::<String>("strip-cwd-prefix").map(|s| s.clone());
    let strip_cwd_prefix = if let Some(val) = strip_cwd_prefix_opt {
        match val.as_str() { "always"=>true, "never"=>false, "auto"=>{ if print0 { false } else { true } }, _=>true }
    } else { if print0 { false } else { true } };
    for res_path in &results {
        let mut out_path: String;
        if is_absolute {
            match res_path.canonicalize() { Ok(p)=>out_path=p.to_string_lossy().to_string(), Err(_)=>out_path=res_path.to_string_lossy().to_string() }
        } else {
            let s = res_path.to_string_lossy().to_string();
            let mut tmp = if s.starts_with("./") { s[2..].to_string() } else { s };
            if !strip_cwd_prefix {
                if !tmp.starts_with("./") && !tmp.starts_with("/") { tmp = format!(".{}{}", path_sep, tmp); }
            }
            out_path = tmp;
        }
        if path_sep != std::path::MAIN_SEPARATOR.to_string() { out_path = out_path.replace(std::path::MAIN_SEPARATOR, &path_sep); }
        let is_dir = res_path.is_dir();
        if is_dir && !out_path.ends_with(&path_sep) { out_path.push_str(&path_sep); }
        if let Some(ref fmt) = format_opt {
            let formatted = apply_format(fmt, res_path, &path_sep);
            if print0 {
                let mut p0 = formatted.clone();
                if !strip_cwd_prefix && !is_absolute {
                    if !p0.starts_with("./") && !p0.starts_with("/") { p0 = format!(".{}{}", path_sep, p0); }
                }
                print!("{}\0", p0);
            } else { println!("{}", formatted); }
        } else {
            let mut display_path = out_path.clone();
            if use_hyperlink {
                let abs_path = match res_path.canonicalize() { Ok(p)=>p, Err(_)=>{ let cwd=std::env::current_dir().unwrap_or(PathBuf::from(".")); cwd.join(res_path) } };
                let hostname = get_hostname();
                let url = format!("file://{}{}", hostname, abs_path.to_string_lossy());
                if use_color {
                    let colored = colorize_path(&res_path, &display_path);
                    display_path = format!("\x1b]8;;{}\x1b\\{}\x1b]8;;\x1b\\", url, colored);
                } else {
                    display_path = format!("\x1b]8;;{}\x1b\\{}\x1b]8;;\x1b\\", url, display_path);
                }
            } else if use_color {
                display_path = colorize_path(&res_path, &display_path);
            }
            if print0 { print!("{}\0", display_path); } else { println!("{}", display_path); }
        }
    }
}

fn expand_placeholder(template: &str, path: &Path, sep: &str, is_absolute: bool, strip: bool) -> String {
    // Handle placeholders: {}, {/}, {//}, {.}, {/.}, plus escaping {{ }}
    // For exec, path handling: path should have ./ prefix if not stripped and not absolute
    let path_str_raw = path.to_string_lossy().to_string();
    let path_str_for_placeholder = if path_str_raw.is_empty() {
        "".to_string()
    } else {
        let mut s = if path_str_raw.starts_with("./") { path_str_raw[2..].to_string() } else { path_str_raw.clone() };
        if !strip && !is_absolute {
            if !s.starts_with("./") && !s.starts_with("/") && !s.is_empty() {
                s = format!(".{}{}", sep, s);
            }
        }
        // Apply sep
        let mut ps = s;
        if sep != std::path::MAIN_SEPARATOR.to_string() {
            ps = ps.replace(std::path::MAIN_SEPARATOR, sep);
        }
        // For dir, keep trailing slash? fd's exec placeholders preserve trailing slash? Let's see: earlier we tested fd txt -x echo {//} gave "./a" not "./a/"? Actually for file a/b/file3.txt, {//} gave ./a/b, not with slash. For dir, what does {//} give? We tested earlier dir placeholder but not conclusively.
        // We'll keep as is without adding trailing slash for placeholder {}? But original fd for {} includes path without trailing slash? Let's check: fd with pattern txt -x echo {} gave "./a/b/file3.txt" (file, no trailing slash). For directory, {} would be directory path without trailing slash? In fd, directories are listed with trailing slash, but placeholder {} probably gives path without trailing slash? Let's check for directory: we need to test.
        ps
    };

    // Compute other placeholders
    let basename = Path::new(&path_str_for_placeholder).file_name().and_then(|n| n.to_str()).unwrap_or("").to_string();
    // For basename, strip trailing slash? If path ends with /, file_name may be dir name? Let's handle
    let parent = {
        let p = Path::new(&path_str_for_placeholder);
        // If path ends with /, parent is parent of dir?
        // For path "./a/b/file.txt", parent is "./a/b"
        // For path "./a/", parent is "."? Let's use parent method but handle dot
        let parent_path = if path_str_for_placeholder.ends_with(sep) {
            // Remove trailing sep for parent calculation
            let trimmed = path_str_for_placeholder.trim_end_matches(sep);
            Path::new(trimmed).parent().map(|pp| pp.to_string_lossy().to_string()).unwrap_or_else(|| ".".to_string())
        } else {
            p.parent().map(|pp| pp.to_string_lossy().to_string()).unwrap_or_else(|| ".".to_string())
        };
        let pp = if parent_path.is_empty() { ".".to_string() } else { parent_path };
        pp
    };
    let path_without_ext = {
        let p = Path::new(&path_str_for_placeholder);
        let stem = p.file_stem().and_then(|s| s.to_str()).unwrap_or("");
        if let Some(parent) = p.parent() {
            let parent_str = parent.to_string_lossy().to_string();
            if parent_str.is_empty() { stem.to_string() } else { format!("{}{}{}", parent_str, sep, stem) }
        } else { stem.to_string() }
    };
    let basename_without_ext = {
        let p = Path::new(&basename);
        p.file_stem().and_then(|s| s.to_str()).unwrap_or("").to_string()
    };

    let mut result = String::new();
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '{' {
            if i+1 < chars.len() && chars[i+1] == '{' { result.push('{'); i+=2; continue; }
            if i+1 < chars.len() && chars[i+1] == '}' {
                result.push_str(&path_str_for_placeholder);
                i+=2; continue;
            }
            if i+2 < chars.len() && chars[i+1] == '/' && chars[i+2] == '}' {
                result.push_str(&basename);
                i+=3; continue;
            }
            if i+3 < chars.len() && chars[i+1] == '/' && chars[i+2] == '/' && chars[i+3] == '}' {
                result.push_str(&parent);
                i+=4; continue;
            }
            if i+2 < chars.len() && chars[i+1] == '.' && chars[i+2] == '}' {
                result.push_str(&path_without_ext);
                i+=3; continue;
            }
            if i+3 < chars.len() && chars[i+1] == '/' && chars[i+2] == '.' && chars[i+3] == '}' {
                result.push_str(&basename_without_ext);
                i+=4; continue;
            }
            result.push(chars[i]); i+=1;
        } else if chars[i] == '}' {
            if i+1 < chars.len() && chars[i+1] == '}' { result.push('}'); i+=2; continue; }
            result.push(chars[i]); i+=1;
        } else { result.push(chars[i]); i+=1; }
    }
    result
}

fn get_hostname() -> String {
    if let Ok(content) = fs::read_to_string("/etc/hostname") { return content.trim().to_string(); }
    if let Ok(content) = fs::read_to_string("/proc/sys/kernel/hostname") { return content.trim().to_string(); }
    if let Ok(h) = std::env::var("HOSTNAME") { return h; }
    "localhost".to_string()
}

fn colorize_path(path: &Path, display: &str) -> String {
    let meta = fs::symlink_metadata(path);
    if let Ok(m) = meta {
        if m.file_type().is_symlink() {
            if fs::metadata(path).is_err() { return format!("\x1b[48;5;203;38;5;16m{}\x1b[0m", display); } else { return format!("\x1b[38;5;203m{}\x1b[0m", display); }
        }
        if m.is_dir() {
            if display.contains('/') {
                let mut colored = String::new();
                let mut remaining = display;
                while let Some(idx) = remaining.find('/') {
                    let (dir_part, rest) = remaining.split_at(idx);
                    if !dir_part.is_empty() { colored.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", dir_part)); }
                    colored.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", "/"));
                    remaining = &rest[1..];
                }
                if !remaining.is_empty() { colored.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", remaining)); }
                return colored;
            } else { return format!("\x1b[38;5;81m{}\x1b[0m", display); }
        }
        if m.is_file() {
            let mode=m.mode();
            if mode & 0o111 !=0 {
                if display.contains('/') {
                    if let Some(idx) = display.rfind('/') {
                        let dir_part = &display[..=idx];
                        let file_part = &display[idx+1..];
                        if file_part.is_empty() { return format!("\x1b[38;5;81m{}\x1b[0m", display); }
                        else {
                            let mut colored_dir = String::new();
                            let mut rem = dir_part;
                            while let Some(slash_idx) = rem.find('/') {
                                let (comp, rest) = rem.split_at(slash_idx);
                                if !comp.is_empty() { colored_dir.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", comp)); }
                                colored_dir.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", "/"));
                                rem = &rest[1..];
                            }
                            if !rem.is_empty() { colored_dir.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", rem)); }
                            return format!("{}{}", colored_dir, format!("\x1b[1;38;5;203m{}\x1b[0m", file_part));
                        }
                    }
                }
                return format!("\x1b[1;38;5;203m{}\x1b[0m", display);
            }
        }
        let mode=m.mode();
        if mode & 0o170000 == 0o10000 { return format!("\x1b[48;5;81;38;5;16m{}\x1b[0m", display); }
    }
    let path_str = path.to_string_lossy().to_lowercase();
    let ext = Path::new(&path_str).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    let archive_exts = ["tar","tgz","zip","gz","bz","bz2","xz","7z","rar","deb","rpm","jar","z"];
    let media_exts = ["jpg","jpeg","png","gif","bmp","ppm","tga","xbm","xpm","tif","tiff","svg","svgz","mng","pcx","mov","mpg","mpeg","m2v","mkv","webm","ogm","mp4","m4v","mp4v","vob","qt","nuv","wmv","asf","rm","rmvb","flc","avi","fli","flv","gl","dl","xcf","xwd","yuv","cgm","emf","ogv","ogx","aac","au","flac","m4a","mid","midi","mka","mp3","mpc","ogg","ra","wav","oga","opus","spx","xspf"];
    let source_exts = ["rs","py","c","cpp","h","go","java","js","ts","sh","bash","zsh","rb","pl","php","lua","kt","swift","dart"];
    let text_exts = ["txt","md","rst","csv"];
    let doc_exts = ["doc","docx","xls","xlsx","ppt","pptx"];
    let config_exts = ["json","toml","yaml","yml","ini","conf","cfg","cnf"];
    let file_color_code = if archive_exts.contains(&ext.as_str()) || path_str.ends_with(".tar.gz") || path_str.ends_with(".tar.bz2") { "\x1b[4;38;5;203m" }
    else if ext=="o" { "\x1b[38;5;243m" }
    else if media_exts.contains(&ext.as_str()) { "\x1b[38;5;208m" }
    else if source_exts.contains(&ext.as_str()) { "\x1b[38;5;48m" }
    else if text_exts.contains(&ext.as_str()) { "\x1b[38;5;185m" }
    else if doc_exts.contains(&ext.as_str()) { "\x1b[38;5;186m" }
    else if config_exts.contains(&ext.as_str()) { "\x1b[38;5;149m" }
    else {
        let file_name = Path::new(&path_str).file_name().and_then(|n| n.to_str()).unwrap_or("").to_lowercase();
        if file_name=="makefile" || file_name=="gnumakefile" || file_name=="cmakelists.txt" { "\x1b[38;5;149m" } else { "" }
    };
    if file_color_code.is_empty() {
        if display.contains('/') {
            if let Some(idx) = display.rfind('/') {
                let dir_part = &display[..=idx];
                let file_part = &display[idx+1..];
                if file_part.is_empty() { return format!("\x1b[38;5;81m{}\x1b[0m", display); }
                else {
                    let mut colored_dir = String::new();
                    let mut rem = dir_part;
                    while let Some(slash_idx) = rem.find('/') {
                        let (comp, rest) = rem.split_at(slash_idx);
                        if !comp.is_empty() { colored_dir.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", comp)); }
                        colored_dir.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", "/"));
                        rem = &rest[1..];
                    }
                    if !rem.is_empty() { colored_dir.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", rem)); }
                    return format!("{}{}", colored_dir, file_part);
                }
            }
        }
        return display.to_string();
    } else {
        if display.contains('/') {
            if let Some(idx) = display.rfind('/') {
                let dir_part = &display[..=idx];
                let file_part = &display[idx+1..];
                if file_part.is_empty() { return format!("\x1b[38;5;81m{}\x1b[0m", display); }
                else {
                    let mut colored_dir = String::new();
                    let mut rem = dir_part;
                    while let Some(slash_idx) = rem.find('/') {
                        let (comp, rest) = rem.split_at(slash_idx);
                        if !comp.is_empty() { colored_dir.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", comp)); }
                        colored_dir.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", "/"));
                        rem = &rest[1..];
                    }
                    if !rem.is_empty() { colored_dir.push_str(&format!("\x1b[38;5;81m{}\x1b[0m", rem)); }
                    return format!("{}{}{}\x1b[0m", colored_dir, file_color_code, file_part);
                }
            }
        }
        return format!("{}{}\x1b[0m", file_color_code, display);
    }
}
fn apply_format(fmt: &str, path: &Path, sep: &str) -> String {
    let path_str_raw = path.to_string_lossy().to_string();
    let path_str = if path_str_raw.starts_with("./") { path_str_raw[2..].to_string() } else { path_str_raw.clone() };
    let basename = Path::new(&path_str).file_name().and_then(|n| n.to_str()).unwrap_or("").to_string();
    let parent = if let Some(parent_path) = Path::new(&path_str).parent() {
        let p = parent_path.to_string_lossy().to_string();
        if p.is_empty() { ".".to_string() } else { p }
    } else { ".".to_string() };
    let path_without_ext = {
        let p = Path::new(&path_str);
        let stem = p.file_stem().and_then(|s| s.to_str()).unwrap_or("");
        if let Some(parent) = p.parent() {
            let parent_str = parent.to_string_lossy().to_string();
            if parent_str.is_empty() { stem.to_string() } else { format!("{}{}{}", parent_str, sep, stem) }
        } else { stem.to_string() }
    };
    let basename_without_ext = {
        let p = Path::new(&basename);
        p.file_stem().and_then(|s| s.to_str()).unwrap_or("").to_string()
    };
    let mut result = String::new();
    let chars: Vec<char> = fmt.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '{' {
            if i+1 < chars.len() && chars[i+1] == '{' { result.push('{'); i+=2; continue; }
            if i+1 < chars.len() && chars[i+1] == '}' { let mut ps = path_str.clone(); if sep != std::path::MAIN_SEPARATOR.to_string() { ps = ps.replace(std::path::MAIN_SEPARATOR, sep); } result.push_str(&ps); i+=2; continue; }
            if i+2 < chars.len() && chars[i+1] == '/' && chars[i+2] == '}' { result.push_str(&basename); i+=3; continue; }
            if i+3 < chars.len() && chars[i+1] == '/' && chars[i+2] == '/' && chars[i+3] == '}' { let mut parent_sep = parent.clone(); if sep != std::path::MAIN_SEPARATOR.to_string() { parent_sep = parent_sep.replace(std::path::MAIN_SEPARATOR, sep); } result.push_str(&parent_sep); i+=4; continue; }
            if i+2 < chars.len() && chars[i+1] == '.' && chars[i+2] == '}' { let mut pwe = path_without_ext.clone(); if sep != std::path::MAIN_SEPARATOR.to_string() { pwe = pwe.replace(std::path::MAIN_SEPARATOR, sep); } result.push_str(&pwe); i+=3; continue; }
            if i+3 < chars.len() && chars[i+1] == '/' && chars[i+2] == '.' && chars[i+3] == '}' { result.push_str(&basename_without_ext); i+=4; continue; }
            result.push(chars[i]); i+=1;
