    } else { None };
    let color_when = matches.get_one::<String>("color").unwrap().clone();
    let hyperlink_when = matches.get_one::<String>("hyperlink").unwrap().clone();
    let print0 = matches.get_flag("print0");
    let absolute_path = matches.get_flag("absolute-path");
    let relative_path = matches.get_flag("relative-path");
    let is_absolute = if relative_path { false } else if absolute_path { true } else { false };
    let path_sep = matches.get_one::<String>("path-separator").map(|s| s.clone()).unwrap_or_else(|| std::path::MAIN_SEPARATOR.to_string());
    let format_opt = matches.get_one::<String>("format").map(|s| s.clone());
    let list_details = matches.get_flag("list-details");
    let follow = matches.get_flag("follow");
    let prune = matches.get_flag("prune");
    let one_file_system = matches.get_flag("one-file-system");
    let show_errors = matches.get_flag("show-errors");
    let max_results_opt = if matches.get_flag("1") { Some(1) } else { matches.get_one::<usize>("max-results").cloned() };
    let quiet = matches.get_flag("quiet");
    let ignore_file_opt = matches.get_one::<String>("ignore-file").map(|s| s.clone());
    let batch_size = matches.get_one::<usize>("batch-size").cloned().unwrap_or(0);
    let use_color = match color_when.as_str() { "always"=>true, "never"=>false, "auto"=>false, _=>false };
    let use_hyperlink = match hyperlink_when.as_str() { "always"=>true, "never"=>false, "auto"=>use_color, _=>false };
    let mut results: Vec<PathBuf> = Vec::new();
    let mut pruned_dirs: Vec<PathBuf> = Vec::new();
    for root in &valid_roots {
        let mut builder = WalkBuilder::new(root);
        builder.hidden(!hidden);
        if no_ignore {
            builder.ignore(false); builder.git_ignore(false); builder.git_global(false); builder.git_exclude(false); builder.require_git(false);
        } else if no_ignore_vcs {
            builder.git_ignore(false); builder.git_global(false); builder.git_exclude(false); builder.ignore(true);
        } else {
            builder.ignore(true); builder.git_ignore(true); builder.git_global(true); builder.git_exclude(true);
            if no_require_git { builder.require_git(false); } else if require_git { builder.require_git(true); } else { builder.require_git(true); }
        }
        if no_ignore_parent { builder.parents(false); } else { builder.parents(true); }
        builder.follow_links(follow);
        if let Some(md) = max_depth { builder.max_depth(Some(md)); }
        if let Some(ref ignore_file) = ignore_file_opt { builder.add_ignore(Path::new(ignore_file)); }
        if one_file_system { builder.same_file_system(true); }
        if let Some(threads) = matches.get_one::<usize>("threads") { builder.threads(*threads); }
        let walker = builder.build();
        for entry in walker {
            let entry = match entry {
                Ok(e) => e,
                Err(err) => { if show_errors { eprintln!("[fd error]: {}", err); } continue; }
            };
            let path = entry.path().to_path_buf();
            let depth = entry.depth();
            if depth==0 { continue; }
            if let Some(min_d) = min_depth { if depth < min_d { continue; } }
            if prune {
                let mut skip = false;
                for pd in &pruned_dirs { if path.starts_with(pd) && path != *pd { skip=true; break; } }
                if skip { continue; }
            }
            let mut should_ignore_contain = false;
            if !ignore_contain.is_empty() {
                for anc in path.ancestors().skip(1) {
                    for ic_name in &ignore_contain {
                        let candidate = anc.join(ic_name);
                        if candidate.exists() { should_ignore_contain=true; break; }
                    }
                    if should_ignore_contain { break; }
                }
                if !should_ignore_contain && path.is_dir() {
                    for ic_name in &ignore_contain { if path.join(ic_name).exists() { should_ignore_contain=true; break; } }
                }
            }
            if should_ignore_contain { continue; }
            if let Some(ref excl_set) = exclude_globset {
                let file_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
                let path_str = path.to_string_lossy();
                let mut is_excluded = false;
                if excl_set.is_match(file_name) || excl_set.is_match(path_str.as_ref()) { is_excluded=true; }
                if !is_excluded {
                    for anc in path.ancestors().skip(1) {
                        if let Some(fname) = anc.file_name().and_then(|n| n.to_str()) { if excl_set.is_match(fname) { is_excluded=true; break; } }
                        if excl_set.is_match(anc.to_string_lossy().as_ref()) { is_excluded=true; break; }
                    }
                }
                if is_excluded { continue; }
            }
            let meta = match fs::symlink_metadata(&path) { Ok(m)=>m, Err(_)=>{ continue; } };
            if !type_filters.is_empty() {
                let mut type_match = false;
                for tf in &type_filters {
                    match tf {
                        FileTypeFilter::File => { if meta.is_file() { type_match=true; } },
                        FileTypeFilter::Directory => { if meta.is_dir() { type_match=true; } },
                        FileTypeFilter::Symlink => { if meta.file_type().is_symlink() { type_match=true; } },
                        FileTypeFilter::Executable => { if meta.is_file() { let mode=meta.mode(); if mode & 0o111 !=0 { type_match=true; } } },
                        FileTypeFilter::Empty => {
                            if meta.is_file() { if meta.len()==0 { type_match=true; } }
                            else if meta.is_dir() { if let Ok(rd)=fs::read_dir(&path) { if rd.count()==0 { type_match=true; } } }
                        },
                        FileTypeFilter::Socket => { let mode=meta.mode(); if mode & 0o170000 == 0o140000 { type_match=true; } },
                        FileTypeFilter::Pipe => { let mode=meta.mode(); if mode & 0o170000 == 0o10000 { type_match=true; } },
                        FileTypeFilter::BlockDevice => { let mode=meta.mode(); if mode & 0o170000 == 0o60000 { type_match=true; } },
                        FileTypeFilter::CharDevice => { let mode=meta.mode(); if mode & 0o170000 == 0o20000 { type_match=true; } },
                    }
                }
                if !type_match { continue; }
            }
            if !ext_filters.is_empty() {
                if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
                    let ext_lower = ext.to_lowercase();
                    if !ext_filters.contains(&ext_lower) { continue; }
                } else { continue; }
            }
            if !size_filters.is_empty() {
                if !meta.is_file() { continue; }
                let file_size = meta.len();
                let mut size_ok = true;
                for sf in &size_filters {
                    match sf.kind {
                        '+' => { if file_size < sf.size { size_ok=false; break; } },
                        '-' => { if file_size > sf.size { size_ok=false; break; } },
                        '=' => { if file_size != sf.size { size_ok=false; break; } },
                        _ => {}
                    }
                }
                if !size_ok { continue; }
            }
            if let Some(ref within_dt) = changed_within_dt {
                let mtime = meta.mtime() as i64;
                let mtime_dt = Utc.timestamp_opt(mtime, 0).unwrap();
                if mtime_dt < *within_dt { continue; }
            }
            if let Some(ref before_dt) = changed_before_dt {
                let mtime = meta.mtime() as i64;
                let mtime_dt = Utc.timestamp_opt(mtime, 0).unwrap();
                if mtime_dt > *before_dt { continue; }
            }
            if let Some(ref of) = owner_filter { if !check_owner(&meta, of) { continue; } }
            let match_target = if matches.get_flag("full-path") {
                match path.canonicalize() { Ok(p)=>p.to_string_lossy().to_string(), Err(_)=>path.to_string_lossy().to_string() }
            } else {
                path.file_name().and_then(|n| n.to_str()).unwrap_or("").to_string()
            };
            let mut matched = false;
            if pattern_str.is_empty() { matched=true; }
            else if glob_flag {
                if let Some(ref set) = main_globset_opt { matched=set.is_match(&match_target); }
            } else {
                if let Some(ref re) = main_regex_opt { matched=re.is_match(&match_target); }
            }
            if !matched { continue; }
            let mut and_ok = true;
            for (idx, _) in and_patterns.iter().enumerate() {
                let target = if matches.get_flag("full-path") {
                    match path.canonicalize() { Ok(p)=>p.to_string_lossy().to_string(), Err(_)=>path.to_string_lossy().to_string() }
                } else { path.file_name().and_then(|n| n.to_str()).unwrap_or("").to_string() };
                if glob_flag {
                    if idx < and_globs.len() { if !and_globs[idx].is_match(&target) { and_ok=false; break; } }
                } else {
                    if idx < and_regexes.len() { if !and_regexes[idx].is_match(&target) { and_ok=false; break; } }
                }
            }
            if !and_ok { continue; }
            results.push(path.clone());
            if prune && path.is_dir() { pruned_dirs.push(path.clone()); }
        }
    }
    results.sort();
    if let Some(max) = max_results_opt { if results.len() > max { results.truncate(max); } }
    if quiet { if results.is_empty() { std::process::exit(1); } else { std::process::exit(0); } }

    if !exec_commands.is_empty() || !exec_batch_commands.is_empty() {
        let use_null_sep = print0;
        let strip_cwd_prefix_opt = matches.get_one::<String>("strip-cwd-prefix").map(|s| s.clone());
        let strip_for_exec = if let Some(val) = strip_cwd_prefix_opt {
            match val.as_str() { "always"=>true, "never"=>false, "auto"=>false, _=>false }
        } else { false };
        let batch_size_val = batch_size;

        if !exec_batch_commands.is_empty() {
            for batch_cmd_template in &exec_batch_commands {
                let has_placeholder = batch_cmd_template.iter().any(|arg| arg.contains("{}") || arg.contains("{/}") || arg.contains("{//}") || arg.contains("{.}") || arg.contains("{/.}"));
                let mut cmd_template = batch_cmd_template.clone();
                if !has_placeholder { cmd_template.push("{}".to_string()); }
                let mut placeholder_kinds: std::collections::HashSet<String> = std::collections::HashSet::new();
                for arg in &cmd_template {
                    if arg.contains("{}") { placeholder_kinds.insert("{}".to_string()); }
                    if arg.contains("{/}") { placeholder_kinds.insert("{/}".to_string()); }
                    if arg.contains("{//}") { placeholder_kinds.insert("{//}".to_string()); }
                    if arg.contains("{.}") { placeholder_kinds.insert("{.}".to_string()); }
                    if arg.contains("{/.}") { placeholder_kinds.insert("{/.}".to_string()); }
                }
                if placeholder_kinds.len() > 1 {
                    eprintln!("error: Only one placeholder allowed for batch commands");
                    eprintln!("\nUsage: fd [OPTIONS] [pattern] [path]...\n\nFor more information, try '--help'.");
                    std::process::exit(2);
                }
                let batches: Vec<Vec<PathBuf>> = if batch_size_val == 0 {
                    vec![results.clone()]
                } else {
                    let mut b: Vec<Vec<PathBuf>> = Vec::new();
                    let mut current: Vec<PathBuf> = Vec::new();
                    for r in &results {
                        current.push(r.clone());
                        if current.len() >= batch_size_val {
                            b.push(current.clone());
                            current.clear();
                        }
                    }
                    if !current.is_empty() { b.push(current); }
                    b
                };
                for batch in batches {
                    let mut exec_args: Vec<String> = Vec::new();
                    for template_arg in &cmd_template {
                        if template_arg.contains("{}") || template_arg.contains("{/}") || template_arg.contains("{//}") || template_arg.contains("{.}") || template_arg.contains("{/.}") {
                            for res_path in &batch {
                                let expanded = expand_placeholder(template_arg, res_path, &path_sep, is_absolute, strip_for_exec);
                                exec_args.push(expanded);
                            }
                        } else {
                            let esc = template_arg.replace("{{", "{").replace("}}", "}");
                            exec_args.push(esc);
                        }
                    }
                    if exec_args.is_empty() { continue; }
                    let cmd_name = exec_args[0].clone();
                    let cmd_args = &exec_args[1..];
                    let mut child = process::Command::new(cmd_name).args(cmd_args).spawn().unwrap_or_else(|e| { eprintln!("Failed to execute: {}", e); std::process::exit(1); });
                    let _ = child.wait();
                }
            }
        }

        if !exec_commands.is_empty() {
            for res_path in &results {
                for exec_cmd_template in &exec_commands {
                    let has_placeholder = exec_cmd_template.iter().any(|arg| arg.contains("{}") || arg.contains("{/}") || arg.contains("{//}") || arg.contains("{.}") || arg.contains("{/.}"));
                    let mut cmd_template = exec_cmd_template.clone();
                    if !has_placeholder { cmd_template.push("{}".to_string()); }
                    let mut exec_args: Vec<String> = Vec::new();
                    for template_arg in &cmd_template {
                        let expanded = expand_placeholder(template_arg, res_path, &path_sep, is_absolute, strip_for_exec);
                        exec_args.push(expanded);
                    }
                    if exec_args.is_empty() { continue; }
                    let cmd_name = exec_args[0].clone();
                    let cmd_args = &exec_args[1..];
                    let mut child = process::Command::new(cmd_name).args(cmd_args).spawn().unwrap_or_else(|e| { eprintln!("Failed to execute: {}", e); std::process::exit(1); });
                    let _ = child.wait();
                    if use_null_sep {
                        print!("\0");
                        use std::io::Write;
                        std::io::stdout().flush().unwrap();
                    }
                }
            }
        }
        return;
    }

    if list_details {
        let mut sorted = results.clone(); sorted.sort();
        let mut cmd_ls = process::Command::new("ls");
        cmd_ls.arg("-l"); cmd_ls.arg("-d");
        for p in &sorted {
            let mut out_path = if is_absolute {
                match p.canonicalize() { Ok(pp)=>pp.to_string_lossy().to_string(), Err(_)=>p.to_string_lossy().to_string() }
            } else {
                let s = p.to_string_lossy().to_string();
                if s.starts_with("./") { s } else { format!("./{}", s) }
            };
            if path_sep != std::path::MAIN_SEPARATOR.to_string() { out_path = out_path.replace(std::path::MAIN_SEPARATOR, &path_sep); }
            cmd_ls.arg(out_path);
        }
        let output = cmd_ls.output().expect("failed to execute ls");
        print!("{}", String::from_utf8_lossy(&output.stdout));
        if !output.stderr.is_empty() { eprint!("{}", String::from_utf8_lossy(&output.stderr)); }
        return;
    }

    let strip_cwd_prefix_opt = matches.get_one::<String>("strip-cwd-prefix").map(|s| s.clone());
    let strip_cwd_prefix = if let Some(val) = strip_cwd_prefix_opt {
        match val.as_str() { "always"=>true, "never"=>false, "auto"=>{ if print0 { false } else { true } }, _=>true }
    } else { if print0 { false } else { true } };
    for res_path in &results {
        let mut out_path: String;
        if is_absolute {
            match res_path.canonicalize() { Ok(p)=>out_path=p.to_string_lossy().to_string(), Err(_)=>out_path=res_path.to_string_lossy().to_string() }
        } else {
            let s = res_path.to_string_lossy().to_string();
            let mut tmp = if s.starts_with("./") { s[2..].to_string() } else { s };
            if !strip_cwd_prefix {
                if !tmp.starts_with("./") && !tmp.starts_with("/") { tmp = format!(".{}{}", path_sep, tmp); }
            }
            out_path = tmp;
        }
        if path_sep != std::path::MAIN_SEPARATOR.to_string() { out_path = out_path.replace(std::path::MAIN_SEPARATOR, &path_sep); }
        let is_dir = res_path.is_dir();
        if is_dir && !out_path.ends_with(&path_sep) { out_path.push_str(&path_sep); }
        if let Some(ref fmt) = format_opt {
            let formatted = apply_format(fmt, res_path, &path_sep);
            if print0 {
                let mut p0 = formatted.clone();
                if !strip_cwd_prefix && !is_absolute {
                    if !p0.starts_with("./") && !p0.starts_with("/") { p0 = format!(".{}{}", path_sep, p0); }
                }
                print!("{}\0", p0);
            } else { println!("{}", formatted); }
        } else {
            let mut display_path = out_path.clone();
            if use_hyperlink {
                let abs_path = match res_path.canonicalize() { Ok(p)=>p, Err(_)=>{ let cwd=std::env::current_dir().unwrap_or(PathBuf::from(".")); cwd.join(res_path) } };
                let hostname = get_hostname();
                let url = format!("file://{}{}", hostname, abs_path.to_string_lossy());
                if use_color {
                    let colored = colorize_path(&res_path, &display_path);
                    display_path = format!("\x1b]8;;{}\x1b\\{}\x1b]8;;\x1b\\", url, colored);
                } else {
                    display_path = format!("\x1b]8;;{}\x1b\\{}\x1b]8;;\x1b\\", url, display_path);
                }
            } else if use_color {
                display_path = colorize_path(&res_path, &display_path);
            }
            if print0 { print!("{}\0", display_path); } else { println!("{}", display_path); }
        }
    }
}
