use std::path::{Path, PathBuf};
use clap::{Command as ClapCommand, Arg, ArgAction, value_parser};
use regex::Regex;
use globset::{Glob, GlobSet, GlobSetBuilder};
use ignore::WalkBuilder;
use chrono::{DateTime, Utc, TimeZone, NaiveDateTime, Local};
use std::os::unix::fs::MetadataExt;
use std::fs;
use std::process;

#[derive(Debug)] enum FileTypeFilter { File, Directory, Symlink, Executable, Empty, Socket, Pipe, BlockDevice, CharDevice }
fn parse_file_type(s: &str) -> Option<FileTypeFilter> {
    match s.to_lowercase().as_str() {
        "f" | "file" => Some(FileTypeFilter::File),
        "d" | "dir" | "directory" => Some(FileTypeFilter::Directory),
        "l" | "symlink" => Some(FileTypeFilter::Symlink),
        "x" | "executable" => Some(FileTypeFilter::Executable),
        "e" | "empty" => Some(FileTypeFilter::Empty),
        "s" | "socket" => Some(FileTypeFilter::Socket),
        "p" | "pipe" => Some(FileTypeFilter::Pipe),
        "b" | "block-device" => Some(FileTypeFilter::BlockDevice),
        "c" | "char-device" => Some(FileTypeFilter::CharDevice),
        _ => None,
    }
}
#[derive(Debug, Clone)] struct SizeFilter { kind: char, size: u64 }
fn parse_size(s: &str) -> Result<SizeFilter, String> {
    let s = s.trim();
    if s.is_empty() { return Err(format!("'{}' is not a valid size constraint. See 'fd --help'.", s)); }
    let (kind, rest) = match s.chars().next().unwrap() {
        '+' => ('+', &s[1..]), '-' => ('-', &s[1..]), _ => ('=', s),
    };
    if rest.is_empty() { return Err(format!("'{}' is not a valid size constraint. See 'fd --help'.", s)); }
    let mut num_end = 0;
    for (i, c) in rest.char_indices() { if c.is_ascii_digit() { num_end = i + c.len_utf8(); } else { break; } }
    if num_end == 0 { return Err(format!("'{}' is not a valid size constraint. See 'fd --help'.", s)); }
    let num_str = &rest[..num_end];
    let unit_str = rest[num_end..].trim().to_lowercase();
    let num: u64 = num_str.parse().map_err(|_| format!("'{}' is not a valid size constraint. See 'fd --help'.", s))?;
    let multiplier: u64 = match unit_str.as_str() {
        "" | "b" => 1, "k" => 1000, "m" => 1000*1000, "g" => 1000*1000*1000, "t" => 1000*1000*1000*1000,
        "ki" => 1024, "mi" => 1024*1024, "gi" => 1024*1024*1024, "ti" => 1024*1024*1024*1024,
        _ => { return Err(format!("'{}' is not a valid size constraint. See 'fd --help'.", s)); }
    };
    Ok(SizeFilter { kind, size: num * multiplier })
}
fn parse_time_filter(s: &str) -> Result<DateTime<Utc>, String> {
    if s.starts_with('@') {
        let num_str = &s[1..];
        let secs: i64 = num_str.parse().map_err(|_| format!("Invalid timestamp"))?;
        return Ok(Utc.timestamp_opt(secs, 0).unwrap());
    }
    if let Some(caps) = Regex::new(r"(?i)^\s*(\d+)\s*([a-z]+)\s*$").unwrap().captures(s) {
        let num: i64 = caps[1].parse().unwrap_or(0);
        let unit = caps[2].to_lowercase();
        let secs = match unit.as_str() {
            "s" | "sec" | "secs" | "second" | "seconds" => num,
            "m" | "min" | "mins" | "minute" | "minutes" => num * 60,
            "h" | "hour" | "hours" => num * 3600,
            "d" | "day" | "days" => num * 86400,
            "w" | "week" | "weeks" => num * 7 * 86400,
            "month" | "months" => num * 30 * 86400,
            "y" | "year" | "years" => num * 365 * 86400,
            _ => 0
        };
        if secs != 0 {
            let now = Utc::now();
            return Ok(now - chrono::Duration::seconds(secs));
        }
    }
    if let Ok(naive) = NaiveDateTime::parse_from_str(&format!("{} 00:00:00", s), "%Y-%m-%d %H:%M:%S") {
        let dt = Local.from_local_datetime(&naive).single().map(|d| d.with_timezone(&Utc)).unwrap_or_else(|| Utc.from_utc_datetime(&naive));
        return Ok(dt);
    }
    if let Ok(naive) = NaiveDateTime::parse_from_str(s, "%Y-%m-%d %H:%M:%S") {
        let dt = Local.from_local_datetime(&naive).single().map(|d| d.with_timezone(&Utc)).unwrap_or_else(|| Utc.from_utc_datetime(&naive));
        return Ok(dt);
    }
    if let Ok(dt) = DateTime::parse_from_rfc3339(s) { return Ok(dt.with_timezone(&Utc)); }
    if let Ok(dt) = s.parse::<DateTime<Utc>>() { return Ok(dt); }
    Err(format!("Unable to parse date/duration: {}", s))
}
#[derive(Debug)] struct OwnerFilter { uid: Option<(u32,bool)>, gid: Option<(u32,bool)>, user_name: Option<(String,bool)>, group_name: Option<(String,bool)>, }
fn get_uid_by_name(name: &str) -> Option<u32> {
    if let Ok(content) = fs::read_to_string("/etc/passwd") {
        for line in content.lines() {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len()>=3 && parts[0]==name { if let Ok(uid)=parts[2].parse::<u32>() { return Some(uid); } }
        }
    }
    None
}
fn get_gid_by_name(name: &str) -> Option<u32> {
    if let Ok(content) = fs::read_to_string("/etc/group") {
        for line in content.lines() {
            let parts: Vec<&str> = line.split(':').collect();
            if parts.len()>=3 && parts[0]==name { if let Ok(gid)=parts[2].parse::<u32>() { return Some(gid); } }
        }
    }
    None
}
fn parse_owner(s: &str) -> Result<OwnerFilter, String> {
    let mut filter = OwnerFilter { uid: None, gid: None, user_name: None, group_name: None };
    if s.contains(':') {
        let parts: Vec<&str> = s.splitn(2, ':').collect();
        let user_part = parts[0]; let group_part = parts[1];
        if !user_part.is_empty() {
            let (neg, name) = if user_part.starts_with('!') { (true, &user_part[1..]) } else { (false, user_part) };
            if name.is_empty() { return Err(format!("'' is not a recognized user name")); }
            if let Ok(uid)=name.parse::<u32>() { filter.uid=Some((uid,neg)); } else { filter.user_name=Some((name.to_string(),neg)); }
        }
        if !group_part.is_empty() {
            let (neg, name) = if group_part.starts_with('!') { (true, &group_part[1..]) } else { (false, group_part) };
            if name.is_empty() { return Err(format!("'' is not a recognized group name")); }
            if let Ok(gid)=name.parse::<u32>() { filter.gid=Some((gid,neg)); } else { filter.group_name=Some((name.to_string(),neg)); }
        }
    } else {
        let (neg, name) = if s.starts_with('!') { (true, &s[1..]) } else { (false, s) };
        if name.is_empty() { return Err(format!("'' is not a recognized user name")); }
        if let Ok(uid)=name.parse::<u32>() { filter.uid=Some((uid,neg)); } else { filter.user_name=Some((name.to_string(),neg)); }
    }
    Ok(filter)
}
fn check_owner(meta: &fs::Metadata, filter: &OwnerFilter) -> bool {
    let uid = meta.uid(); let gid = meta.gid();
    let uid_match = if let Some((filter_uid, neg)) = filter.uid {
        let m = uid == filter_uid; if neg { !m } else { m }
    } else if let Some((ref name, neg)) = filter.user_name {
        if let Some(filter_uid)=get_uid_by_name(name) { let m = uid == filter_uid; if neg { !m } else { m } } else { if neg { true } else { false } }
    } else { true };
    let gid_match = if let Some((filter_gid, neg)) = filter.gid {
        let m = gid == filter_gid; if neg { !m } else { m }
    } else if let Some((ref name, neg)) = filter.group_name {
        if let Some(filter_gid)=get_gid_by_name(name) { let m = gid == filter_gid; if neg { !m } else { m } } else { if neg { true } else { false } }
    } else { true };
    uid_match && gid_match
}
fn apply_format(fmt: &str, path: &Path, sep: &str) -> String {
    let path_str_raw = path.to_string_lossy().to_string();
    let path_str = if path_str_raw.starts_with("./") { path_str_raw[2..].to_string() } else { path_str_raw.clone() };
    let basename = Path::new(&path_str).file_name().and_then(|n| n.to_str()).unwrap_or("").to_string();
    let parent = if let Some(parent_path) = Path::new(&path_str).parent() {
        let p = parent_path.to_string_lossy().to_string();
        if p.is_empty() { ".".to_string() } else { p }
    } else { ".".to_string() };
    let path_without_ext = {
        let p = Path::new(&path_str);
        let stem = p.file_stem().and_then(|s| s.to_str()).unwrap_or("");
        if let Some(parent) = p.parent() {
            let parent_str = parent.to_string_lossy().to_string();
            if parent_str.is_empty() { stem.to_string() } else { format!("{}{}{}", parent_str, sep, stem) }
        } else { stem.to_string() }
    };
    let basename_without_ext = {
        let p = Path::new(&basename);
        p.file_stem().and_then(|s| s.to_str()).unwrap_or("").to_string()
    };
    let mut result = String::new();
    let chars: Vec<char> = fmt.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '{' {
            if i+1 < chars.len() && chars[i+1] == '{' { result.push('{'); i+=2; continue; }
            if i+1 < chars.len() && chars[i+1] == '}' { let mut ps = path_str.clone(); if sep != std::path::MAIN_SEPARATOR.to_string() { ps = ps.replace(std::path::MAIN_SEPARATOR, sep); } result.push_str(&ps); i+=2; continue; }
            if i+2 < chars.len() && chars[i+1] == '/' && chars[i+2] == '}' { result.push_str(&basename); i+=3; continue; }
            if i+3 < chars.len() && chars[i+1] == '/' && chars[i+2] == '/' && chars[i+3] == '}' { let mut parent_sep = parent.clone(); if sep != std::path::MAIN_SEPARATOR.to_string() { parent_sep = parent_sep.replace(std::path::MAIN_SEPARATOR, sep); } result.push_str(&parent_sep); i+=4; continue; }
            if i+2 < chars.len() && chars[i+1] == '.' && chars[i+2] == '}' { let mut pwe = path_without_ext.clone(); if sep != std::path::MAIN_SEPARATOR.to_string() { pwe = pwe.replace(std::path::MAIN_SEPARATOR, sep); } result.push_str(&pwe); i+=3; continue; }
            if i+3 < chars.len() && chars[i+1] == '/' && chars[i+2] == '.' && chars[i+3] == '}' { result.push_str(&basename_without_ext); i+=4; continue; }
            result.push(chars[i]); i+=1;
        } else if chars[i] == '}' {
            if i+1 < chars.len() && chars[i+1] == '}' { result.push('}'); i+=2; continue; }
            result.push(chars[i]); i+=1;
        } else { result.push(chars[i]); i+=1; }
    }
    result
}
fn get_hostname() -> String {
    if let Ok(content) = fs::read_to_string("/etc/hostname") { return content.trim().to_string(); }
    if let Ok(content) = fs::read_to_string("/proc/sys/kernel/hostname") { return content.trim().to_string(); }
