fn file_color_code_for_path(path: &Path) -> &'static str {
    let path_str = path.to_string_lossy().to_lowercase();
    let ext = Path::new(&path_str).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    let archive_exts = ["tar","tgz","zip","gz","bz","bz2","xz","7z","rar","deb","rpm","jar","z"];
    let media_exts = ["jpg","jpeg","png","gif","bmp","ppm","tga","xbm","xpm","tif","tiff","svg","svgz","mng","pcx","mov","mpg","mpeg","m2v","mkv","webm","ogm","mp4","m4v","mp4v","vob","qt","nuv","wmv","asf","rm","rmvb","flc","avi","fli","flv","gl","dl","xcf","xwd","yuv","cgm","emf","ogv","ogx","aac","au","flac","m4a","mid","midi","mka","mp3","mpc","ogg","ra","wav","oga","opus","spx","xspf"];
    let source_exts = ["rs","py","c","cpp","h","go","java","js","ts","sh","bash","zsh","rb","pl","php","lua","kt","swift","dart"];
    let text_exts = ["txt","md","rst","csv"];
    let doc_exts = ["doc","docx","xls","xlsx","ppt","pptx"];
    let config_exts = ["json","toml","yaml","yml","ini","conf","cfg","cnf"];
    if archive_exts.contains(&ext.as_str()) || path_str.ends_with(".tar.gz") || path_str.ends_with(".tar.bz2") { return "\x1b[4;38;5;203m"; }
    if ext=="o" { return "\x1b[38;5;243m"; }
    if media_exts.contains(&ext.as_str()) { return "\x1b[38;5;208m"; }
    if source_exts.contains(&ext.as_str()) { return "\x1b[38;5;48m"; }
    if text_exts.contains(&ext.as_str()) { return "\x1b[38;5;185m"; }
    if doc_exts.contains(&ext.as_str()) { return "\x1b[38;5;186m"; }
    if config_exts.contains(&ext.as_str()) { return "\x1b[38;5;149m"; }
    let file_name = Path::new(&path_str).file_name().and_then(|n| n.to_str()).unwrap_or("").to_lowercase();
    if file_name=="makefile" || file_name=="gnumakefile" || file_name=="cmakelists.txt" { return "\x1b[38;5;149m"; }
    ""
}
fn colorize_path(path: &Path, display: &str) -> String {
    // Check special types first
    if let Ok(m) = fs::symlink_metadata(path) {
        if m.file_type().is_symlink() {
            if fs::metadata(path).is_err() {
                return format!("\x1b[48;5;203;38;5;16m{}\x1b[0m", display);
            } else {
                // For symlink, original colors whole display as symlink color, but with dir split? Actually symlink path may contain dir components.
                // For simplicity, if display has slash, color dir part as dir and symlink part as symlink?
                // Let's check original behavior for symlink inside dir:
                // We saw earlier for link_to_dir and link_to_file, they were colored as symlink color (203) even when inside subdir? In test_exts_many, subdir/ was dir color, but link_to_dir was colored as symlink? Actually list: subdir/ was dir, but link_to_dir itself was symlink (not inside subdir, it was in root). For file inside subdir, we already have dir part colored as dir and file as file.
                // For symlink inside dir, dir part should be dir color, symlink part as symlink color.
                // We'll implement similar to file case but with symlink color.
                if display.contains('/') {
                    if let Some(idx) = display.rfind('/') {
                        let dir_part = &display[..=idx];
                        let file_part = &display[idx+1..];
                        if file_part.is_empty() {
                            // dir symlink? Actually symlink to dir, display ends with slash? Original for symlink to dir? In earlier test, link_to_dir was colored as symlink but without slash? Actually it didn't have slash.
                            // So fallback
                            return format!("\x1b[38;5;203m{}\x1b[0m", display);
                        } else {
                            // Dir part colored as dir (single block or per component? For file case dir part single block)
                            // For consistency with file case, dir part as single block dir color
                            let dir_colored = format!("\x1b[38;5;81m{}\x1b[0m", dir_part);
                            return format!("{}{}{}\x1b[0m", dir_colored, "\x1b[38;5;203m", file_part);
                        }
                    }
                }
                return format!("\x1b[38;5;203m{}\x1b[0m", display);
            }
        }
        if m.is_dir() {
            // Directory coloring: per original, for path a/ -> a colored, / colored separately
            // For a/b/ -> a/ as one block, b colored, / colored
            // For a/b/c/ -> a/b/ as one, c, /
            // General: for dir path, if it contains '/', we want to color parent path (including slash) as one block dir color, then last component as dir color, then slash as dir color, each with separate escapes?
            // Actually original for a/b/c/ shows: a/b/ as one, c as one, / as one. That's 3 escapes: first is parent dir (a/b/), second is component (c), third is slash.
            // For a/b/, it's a/ as one, b as one, / as one.
            // For a/, it's a as one, / as one.
            // So logic: for dir path ending with /, trim trailing /, then split into parent and last component.
            // If parent is empty or "." -> then it's just last component + slash: two escapes: component, slash.
            // Else parent is like a/b, plus slash => a/b/ as one block, then last component, then slash.
            // But note original for a/b/ had a/ as one block (not a and / separate). Wait earlier we saw for a/b/, first part was a/ as combined, not a + / separate. So for a/b/, parent is a, last is b: parent a/ as one block, b as one, / as one.
            // For a/b/c/, parent a/b/, last c, slash.

            if display.ends_with('/') {
                let trimmed = display.trim_end_matches('/');
                if trimmed.is_empty() {
                    return format!("\x1b[38;5;81m{}\x1b[0m", display);
                }
                if let Some(last_slash_idx) = trimmed.rfind('/') {
                    let parent_part = &display[..=last_slash_idx]; // includes slash, e.g., a/b/ for a/b/c/
                    let last_component = &trimmed[last_slash_idx+1..];
                    // parent_part is already with slash
                    let parent_colored = format!("\x1b[38;5;81m{}\x1b[0m", parent_part);
                    let comp_colored = format!("\x1b[38;5;81m{}\x1b[0m", last_component);
                    let slash_colored = format!("\x1b[38;5;81m{}\x1b[0m", "/");
                    return format!("{}{}{}", parent_colored, comp_colored, slash_colored);
                } else {
                    // No slash in trimmed, e.g., "a"
                    let comp = trimmed;
                    let slash_colored = format!("\x1b[38;5;81m{}\x1b[0m", "/");
                    let comp_colored = format!("\x1b[38;5;81m{}\x1b[0m", comp);
                    return format!("{}{}", comp_colored, slash_colored);
                }
            } else {
                // Dir without trailing slash? Should still be colored? But fd adds trailing slash for dirs, so this case shouldn't happen for dir display, but just in case.
                return format!("\x1b[38;5;81m{}\x1b[0m", display);
            }
        }
        if m.is_file() {
            let mode=m.mode();
            if mode & 0o111 !=0 {
                // executable
                if display.contains('/') {
                    if let Some(idx) = display.rfind('/') {
                        let dir_part = &display[..=idx];
                        let file_part = &display[idx+1..];
                        if !file_part.is_empty() {
                            let dir_colored = format!("\x1b[38;5;81m{}\x1b[0m", dir_part);
                            return format!("{}{}{}\x1b[0m", dir_colored, "\x1b[1;38;5;203m", file_part);
                        }
                    }
                }
                return format!("\x1b[1;38;5;203m{}\x1b[0m", display);
            }
        }
        let mode=m.mode();
        if mode & 0o170000 == 0o10000 {
            return format!("\x1b[48;5;81;38;5;16m{}\x1b[0m", display);
        }
    }

    // Regular file
    let f_color = file_color_code_for_path(path);
    if f_color.is_empty() {
        if display.contains('/') {
            if let Some(idx) = display.rfind('/') {
                let dir_part = &display[..=idx];
                let file_part = &display[idx+1..];
                if file_part.is_empty() {
                    // dir, but we already handled dir case, so this is fallback
                    return format!("\x1b[38;5;81m{}\x1b[0m", display);
                } else {
                    // dir part as single block dir color, file part no color
                    let dir_colored = format!("\x1b[38;5;81m{}\x1b[0m", dir_part);
                    return format!("{}{}", dir_colored, file_part);
                }
            }
        }
        return display.to_string();
    } else {
        if display.contains('/') {
            if let Some(idx) = display.rfind('/') {
                let dir_part = &display[..=idx];
                let file_part = &display[idx+1..];
                if file_part.is_empty() {
                    return format!("\x1b[38;5;81m{}\x1b[0m", display);
                } else {
                    let dir_colored = format!("\x1b[38;5;81m{}\x1b[0m", dir_part);
                    return format!("{}{}{}\x1b[0m", dir_colored, f_color, file_part);
                }
            }
        }
        return format!("{}{}\x1b[0m", f_color, display);
    }
}
fn expand_placeholder(template: &str, path: &Path, sep: &str, is_absolute: bool, strip: bool) -> String {
    let path_str_raw = path.to_string_lossy().to_string();
    let path_str_for_placeholder = if path_str_raw.is_empty() { "".to_string() } else {
        let mut s = if path_str_raw.starts_with("./") { path_str_raw[2..].to_string() } else { path_str_raw.clone() };
        if !strip && !is_absolute {
            if !s.starts_with("./") && !s.starts_with("/") && !s.is_empty() { s = format!(".{}{}", sep, s); }
        }
        let mut ps = s;
        if sep != std::path::MAIN_SEPARATOR.to_string() { ps = ps.replace(std::path::MAIN_SEPARATOR, sep); }
        ps
    };
    let basename = Path::new(&path_str_for_placeholder).file_name().and_then(|n| n.to_str()).unwrap_or("").to_string();
    let parent = {
        let p = Path::new(&path_str_for_placeholder);
        let parent_path = if path_str_for_placeholder.ends_with(sep) {
            let trimmed = path_str_for_placeholder.trim_end_matches(sep);
            Path::new(trimmed).parent().map(|pp| pp.to_string_lossy().to_string()).unwrap_or_else(|| ".".to_string())
        } else {
            p.parent().map(|pp| pp.to_string_lossy().to_string()).unwrap_or_else(|| ".".to_string())
        };
        if parent_path.is_empty() { ".".to_string() } else { parent_path }
    };
    let path_without_ext = {
        let p = Path::new(&path_str_for_placeholder);
        let stem = p.file_stem().and_then(|s| s.to_str()).unwrap_or("");
        if let Some(parent) = p.parent() {
            let parent_str = parent.to_string_lossy().to_string();
            if parent_str.is_empty() { stem.to_string() } else { format!("{}{}{}", parent_str, sep, stem) }
        } else { stem.to_string() }
    };
    let basename_without_ext = {
        let p = Path::new(&basename);
        p.file_stem().and_then(|s| s.to_str()).unwrap_or("").to_string()
    };
    let mut result = String::new();
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '{' {
            if i+1 < chars.len() && chars[i+1] == '{' { result.push('{'); i+=2; continue; }
            if i+1 < chars.len() && chars[i+1] == '}' { result.push_str(&path_str_for_placeholder); i+=2; continue; }
            if i+2 < chars.len() && chars[i+1] == '/' && chars[i+2] == '}' { result.push_str(&basename); i+=3; continue; }
            if i+3 < chars.len() && chars[i+1] == '/' && chars[i+2] == '/' && chars[i+3] == '}' { result.push_str(&parent); i+=4; continue; }
            if i+2 < chars.len() && chars[i+1] == '.' && chars[i+2] == '}' { result.push_str(&path_without_ext); i+=3; continue; }
            if i+3 < chars.len() && chars[i+1] == '/' && chars[i+2] == '.' && chars[i+3] == '}' { result.push_str(&basename_without_ext); i+=4; continue; }
            result.push(chars[i]); i+=1;
        } else if chars[i] == '}' {
            if i+1 < chars.len() && chars[i+1] == '}' { result.push('}'); i+=2; continue; }
            result.push(chars[i]); i+=1;
        } else { result.push(chars[i]); i+=1; }
    }
    result
}

fn main() {
    let raw_args: Vec<String> = std::env::args().collect();
    let mut exec_commands: Vec<Vec<String>> = Vec::new();
    let mut exec_batch_commands: Vec<Vec<String>> = Vec::new();
    let mut i = 0;
    while i < raw_args.len() {
        let arg = &raw_args[i];
        if arg == "-x" || arg == "--exec" {
            i+=1;
            let mut cmd_args: Vec<String> = Vec::new();
            while i < raw_args.len() {
                let a = &raw_args[i];
                if a == ";" { i+=1; break; }
                if a == "-x" || a == "--exec" || a == "-X" || a == "--exec-batch" { break; }
                cmd_args.push(a.clone());
                i+=1;
            }
            if !cmd_args.is_empty() { exec_commands.push(cmd_args); }
            continue;
        } else if arg == "-X" || arg == "--exec-batch" {
            i+=1;
            let mut cmd_args: Vec<String> = Vec::new();
            while i < raw_args.len() {
                let a = &raw_args[i];
                if a == ";" { i+=1; break; }
                if a == "-x" || a == "--exec" || a == "-X" || a == "--exec-batch" { break; }
                cmd_args.push(a.clone());
                i+=1;
            }
            if !cmd_args.is_empty() { exec_batch_commands.push(cmd_args); }
            continue;
        }
        i+=1;
    }

    let mut clap_cmd = ClapCommand::new("fd").version("10.3.0").about("A program to find entries in your filesystem")
        .arg(Arg::new("pattern").required(false))
        .arg(Arg::new("path").num_args(0..))
        .arg(Arg::new("hidden").short('H').long("hidden").action(ArgAction::SetTrue))
        .arg(Arg::new("no-hidden").long("no-hidden").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore").short('I').long("no-ignore").action(ArgAction::SetTrue))
        .arg(Arg::new("ignore").long("ignore").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore-vcs").long("no-ignore-vcs").action(ArgAction::SetTrue))
        .arg(Arg::new("ignore-vcs").long("ignore-vcs").action(ArgAction::SetTrue))
        .arg(Arg::new("no-require-git").long("no-require-git").action(ArgAction::SetTrue))
        .arg(Arg::new("require-git").long("require-git").action(ArgAction::SetTrue))
