        .arg(Arg::new("absolute-path").short('a').long("absolute-path").action(ArgAction::SetTrue))
        .arg(Arg::new("relative-path").long("relative-path").action(ArgAction::SetTrue))
        .arg(Arg::new("list-details").short('l').long("list-details").action(ArgAction::SetTrue))
        .arg(Arg::new("follow").short('L').long("follow").action(ArgAction::SetTrue))
        .arg(Arg::new("no-follow").long("no-follow").action(ArgAction::SetTrue))
        .arg(Arg::new("full-path").short('p').long("full-path").action(ArgAction::SetTrue))
