            eprintln!("\nUsage: executable --search-path <search-path> <pattern> [path]...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        if !roots.is_empty() {
            eprintln!("error: the argument '--strip-cwd-prefix[=<when>]' cannot be used with '[path]...'");
            eprintln!("\nUsage: executable <pattern> <path>...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
