}
fn file_color_code_for_path(path: &Path) -> &'static str {
    let path_str = path.to_string_lossy().to_lowercase();
    let ext = Path::new(&path_str).extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    let archive_exts = ["tar","tgz","zip","gz","bz","bz2","xz","7z","rar","deb","rpm","jar","z"];
    let media_exts = ["jpg","jpeg","png","gif","bmp","ppm","tga","xbm","xpm","tif","tiff","svg","svgz","mng","pcx","mov","mpg","mpeg","m2v","mkv","webm","ogm","mp4","m4v","mp4v","vob","qt","nuv","wmv","asf","rm","rmvb","flc","avi","fli","flv","gl","dl","xcf","xwd","yuv","cgm","emf","ogv","ogx","aac","au","flac","m4a","mid","midi","mka","mp3","mpc","ogg","ra","wav","oga","opus","spx","xspf"];
    let source_exts = ["rs","py","c","cpp","h","go","java","js","ts","sh","bash","zsh","rb","pl","php","lua","kt","swift","dart"];
    let text_exts = ["txt","md","rst","csv"];
    let doc_exts = ["doc","docx","xls","xlsx","ppt","pptx"];
    let config_exts = ["json","toml","yaml","yml","ini","conf","cfg","cnf"];
    if archive_exts.contains(&ext.as_str()) || path_str.ends_with(".tar.gz") || path_str.ends_with(".tar.bz2") { return "\x1b[4;38;5;203m"; }
    if ext=="o" { return "\x1b[38;5;243m"; }
    if media_exts.contains(&ext.as_str()) { return "\x1b[38;5;208m"; }
    if source_exts.contains(&ext.as_str()) { return "\x1b[38;5;48m"; }
    if text_exts.contains(&ext.as_str()) { return "\x1b[38;5;185m"; }
    if doc_exts.contains(&ext.as_str()) { return "\x1b[38;5;186m"; }
    if config_exts.contains(&ext.as_str()) { return "\x1b[38;5;149m"; }
    let file_name = Path::new(&path_str).file_name().and_then(|n| n.to_str()).unwrap_or("").to_lowercase();
    if file_name=="makefile" || file_name=="gnumakefile" || file_name=="cmakelists.txt" { return "\x1b[38;5;149m"; }
    ""
}
fn colorize_path(path: &Path, display: &str) -> String {
    let meta = fs::symlink_metadata(path);
    if let Ok(m) = meta {
        if m.file_type().is_symlink() {
            if fs::metadata(path).is_err() { return format!("\x1b[48;5;203;38;5;16m{}\x1b[0m", display); } else { return format!("\x1b[38;5;203m{}\x1b[0m", display); }
        }
        if m.is_dir() {
            if display.ends_with('/') {
                let trimmed = display.trim_end_matches('/');
                if trimmed.is_empty() { return format!("\x1b[38;5;81m{}\x1b[0m", display); }
                if let Some(last_slash_idx) = trimmed.rfind('/') {
                    let parent_part = &display[..=last_slash_idx];
                    let last_component = &trimmed[last_slash_idx+1..];
                    let parent_colored = format!("\x1b[38;5;81m{}\x1b[0m", parent_part);
                    let comp_colored = format!("\x1b[38;5;81m{}\x1b[0m", last_component);
                    let slash_colored = format!("\x1b[38;5;81m{}\x1b[0m", "/");
                    return format!("{}{}{}", parent_colored, comp_colored, slash_colored);
                } else {
                    let comp = trimmed;
                    let slash_colored = format!("\x1b[38;5;81m{}\x1b[0m", "/");
                    let comp_colored = format!("\x1b[38;5;81m{}\x1b[0m", comp);
                    return format!("{}{}", comp_colored, slash_colored);
                }
            } else { return format!("\x1b[38;5;81m{}\x1b[0m", display); }
        }
        if m.is_file() {
            let mode=m.mode();
            if mode & 0o111 !=0 {
                if display.contains('/') {
                    if let Some(idx) = display.rfind('/') {
                        let dir_part = &display[..=idx];
                        let file_part = &display[idx+1..];
                        if !file_part.is_empty() {
                            let dir_colored = format!("\x1b[38;5;81m{}\x1b[0m", dir_part);
                            return format!("{}{}{}\x1b[0m", dir_colored, "\x1b[1;38;5;203m", file_part);
                        }
                    }
                }
                return format!("\x1b[1;38;5;203m{}\x1b[0m", display);
            }
        }
        let mode=m.mode();
        if mode & 0o170000 == 0o10000 { return format!("\x1b[48;5;81;38;5;16m{}\x1b[0m", display); }
    }
    let f_color = file_color_code_for_path(path);
    if f_color.is_empty() {
        if display.contains('/') {
            if let Some(idx) = display.rfind('/') {
                let dir_part = &display[..=idx];
                let file_part = &display[idx+1..];
                if !file_part.is_empty() {
                    let dir_colored = format!("\x1b[38;5;81m{}\x1b[0m", dir_part);
                    return format!("{}{}", dir_colored, file_part);
                }
            }
        }
        return display.to_string();
    } else {
        if display.contains('/') {
            if let Some(idx) = display.rfind('/') {
                let dir_part = &display[..=idx];
                let file_part = &display[idx+1..];
                if !file_part.is_empty() {
                    let dir_colored = format!("\x1b[38;5;81m{}\x1b[0m", dir_part);
                    return format!("{}{}{}\x1b[0m", dir_colored, f_color, file_part);
                }
            }
        }
        return format!("{}{}\x1b[0m", f_color, display);
    }
}
fn expand_placeholder(template: &str, path: &Path, sep: &str, is_absolute: bool, strip: bool, roots_empty: bool) -> String {
    let path_str_raw = path.to_string_lossy().to_string();
    let path_str_for_placeholder = if path_str_raw.is_empty() { "".to_string() } else {
        let mut s = if path_str_raw.starts_with("./") { path_str_raw[2..].to_string() } else { path_str_raw.clone() };
        if !is_absolute {
            if roots_empty {
                if !strip {
                    if !s.starts_with("./") && !s.starts_with("/") && !s.is_empty() {
                        s = format!(".{}{}", sep, s);
                    }
                }
            } else {
                if !strip {
                    if !s.starts_with("./") && !s.starts_with("/") && !s.is_empty() {
                        s = format!(".{}{}", sep, s);
                    }
                }
            }
        }
        let mut ps = s;
        if sep != std::path::MAIN_SEPARATOR.to_string() { ps = ps.replace(std::path::MAIN_SEPARATOR, sep); }
        ps
    };
    let basename = Path::new(&path_str_for_placeholder).file_name().and_then(|n| n.to_str()).unwrap_or("").to_string();
    let parent = {
        let p = Path::new(&path_str_for_placeholder);
        let parent_path = if path_str_for_placeholder.ends_with(sep) {
            let trimmed = path_str_for_placeholder.trim_end_matches(sep);
            Path::new(trimmed).parent().map(|pp| pp.to_string_lossy().to_string()).unwrap_or_else(|| ".".to_string())
        } else {
            p.parent().map(|pp| pp.to_string_lossy().to_string()).unwrap_or_else(|| ".".to_string())
        };
        if parent_path.is_empty() { ".".to_string() } else { parent_path }
    };
    let path_without_ext = {
        let p = Path::new(&path_str_for_placeholder);
        let stem = p.file_stem().and_then(|s| s.to_str()).unwrap_or("");
        if let Some(parent) = p.parent() {
            let parent_str = parent.to_string_lossy().to_string();
            if parent_str.is_empty() { stem.to_string() } else { format!("{}{}{}", parent_str, sep, stem) }
        } else { stem.to_string() }
    };
    let basename_without_ext = {
        let p = Path::new(&basename);
        p.file_stem().and_then(|s| s.to_str()).unwrap_or("").to_string()
    };
    let mut result = String::new();
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '{' {
            if i+1 < chars.len() && chars[i+1] == '{' { result.push('{'); i+=2; continue; }
            if i+1 < chars.len() && chars[i+1] == '}' { result.push_str(&path_str_for_placeholder); i+=2; continue; }
            if i+2 < chars.len() && chars[i+1] == '/' && chars[i+2] == '}' { result.push_str(&basename); i+=3; continue; }
            if i+3 < chars.len() && chars[i+1] == '/' && chars[i+2] == '/' && chars[i+3] == '}' { result.push_str(&parent); i+=4; continue; }
            if i+2 < chars.len() && chars[i+1] == '.' && chars[i+2] == '}' { result.push_str(&path_without_ext); i+=3; continue; }
            if i+3 < chars.len() && chars[i+1] == '/' && chars[i+2] == '.' && chars[i+3] == '}' { result.push_str(&basename_without_ext); i+=4; continue; }
            result.push(chars[i]); i+=1;
        } else if chars[i] == '}' {
            if i+1 < chars.len() && chars[i+1] == '}' { result.push('}'); i+=2; continue; }
            result.push(chars[i]); i+=1;
        } else { result.push(chars[i]); i+=1; }
    }
    result
}

fn main() {
    let raw_args: Vec<String> = std::env::args().collect();
    // Help handling: intercept -h and --help to print exact original help
    if raw_args.iter().any(|a| a=="--help") {
        print!("{}", HELP_FULL);
        std::process::exit(0);
    }
    if raw_args.iter().any(|a| a=="-h") {
        // Check if it's exactly -h or contains -h as combined short flags? For simplicity, if any arg is -h or contains h in short cluster like -HIh ?
        // We'll look for exact -h or args that contain h and are short flags like -h, -Hh, -lh etc?
        // Simpler: if args contain -h as separate or combined like -H, -h is short for help, but -H is hidden, not help.
        // Original fd -h is separate flag, not combined. So we check exact "-h" or "--help"
        // But also need to handle -h as part of combined like -Hh? Original fd might allow -h combined? Usually -h is help. We'll just check for exact "-h"
        let has_h = raw_args.iter().any(|a| a=="-h");
        if has_h {
            print!("{}", HELP_SHORT);
            std::process::exit(0);
        }
    }

    let mut exec_commands: Vec<Vec<String>> = Vec::new();
    let mut exec_batch_commands: Vec<Vec<String>> = Vec::new();
    let mut i = 0;
    while i < raw_args.len() {
        let arg = &raw_args[i];
        if arg == "-x" || arg == "--exec" {
            i+=1;
            let mut cmd_args: Vec<String> = Vec::new();
            while i < raw_args.len() {
                let a = &raw_args[i];
                if a == ";" { i+=1; break; }
                if a == "-x" || a == "--exec" || a == "-X" || a == "--exec-batch" { break; }
                cmd_args.push(a.clone());
                i+=1;
            }
            if !cmd_args.is_empty() { exec_commands.push(cmd_args); }
            continue;
        } else if arg == "-X" || arg == "--exec-batch" {
            i+=1;
            let mut cmd_args: Vec<String> = Vec::new();
            while i < raw_args.len() {
                let a = &raw_args[i];
                if a == ";" { i+=1; break; }
                if a == "-x" || a == "--exec" || a == "-X" || a == "--exec-batch" { break; }
                cmd_args.push(a.clone());
                i+=1;
            }
            if !cmd_args.is_empty() { exec_batch_commands.push(cmd_args); }
            continue;
        }
        i+=1;
    }

    let mut clap_cmd = ClapCommand::new("fd").version("10.3.0").about("A program to find entries in your filesystem")
        .arg(Arg::new("pattern").required(false))
        .arg(Arg::new("path").num_args(0..))
        .arg(Arg::new("hidden").short('H').long("hidden").action(ArgAction::SetTrue))
        .arg(Arg::new("no-hidden").long("no-hidden").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore").short('I').long("no-ignore").action(ArgAction::SetTrue))
        .arg(Arg::new("ignore").long("ignore").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore-vcs").long("no-ignore-vcs").action(ArgAction::SetTrue))
        .arg(Arg::new("ignore-vcs").long("ignore-vcs").action(ArgAction::SetTrue))
        .arg(Arg::new("no-require-git").long("no-require-git").action(ArgAction::SetTrue))
        .arg(Arg::new("require-git").long("require-git").action(ArgAction::SetTrue))
        .arg(Arg::new("no-ignore-parent").long("no-ignore-parent").action(ArgAction::SetTrue))
        .arg(Arg::new("unrestricted").short('u').long("unrestricted").action(ArgAction::Count))
        .arg(Arg::new("case-sensitive").short('s').long("case-sensitive").action(ArgAction::SetTrue))
        .arg(Arg::new("ignore-case").short('i').long("ignore-case").action(ArgAction::SetTrue))
        .arg(Arg::new("glob").short('g').long("glob").action(ArgAction::SetTrue))
        .arg(Arg::new("regex").long("regex").action(ArgAction::SetTrue))
        .arg(Arg::new("fixed-strings").short('F').long("fixed-strings").action(ArgAction::SetTrue))
        .arg(Arg::new("and").long("and").action(ArgAction::Append))
        .arg(Arg::new("absolute-path").short('a').long("absolute-path").action(ArgAction::SetTrue))
        .arg(Arg::new("relative-path").long("relative-path").action(ArgAction::SetTrue))
        .arg(Arg::new("list-details").short('l').long("list-details").action(ArgAction::SetTrue))
        .arg(Arg::new("follow").short('L').long("follow").action(ArgAction::SetTrue))
        .arg(Arg::new("no-follow").long("no-follow").action(ArgAction::SetTrue))
        .arg(Arg::new("full-path").short('p').long("full-path").action(ArgAction::SetTrue))
        .arg(Arg::new("print0").short('0').long("print0").action(ArgAction::SetTrue))
        .arg(Arg::new("max-depth").short('d').long("max-depth").value_parser(value_parser!(usize)))
        .arg(Arg::new("min-depth").long("min-depth").value_parser(value_parser!(usize)))
        .arg(Arg::new("exact-depth").long("exact-depth").value_parser(value_parser!(usize)))
        .arg(Arg::new("exclude").short('E').long("exclude").action(ArgAction::Append))
        .arg(Arg::new("prune").long("prune").action(ArgAction::SetTrue))
        .arg(Arg::new("type").short('t').long("type").action(ArgAction::Append))
        .arg(Arg::new("extension").short('e').long("extension").action(ArgAction::Append))
        .arg(Arg::new("size").short('S').long("size").action(ArgAction::Append))
        .arg(Arg::new("changed-within").long("changed-within").aliases(["change-newer-than","newer","changed-after"]))
        .arg(Arg::new("changed-before").long("changed-before").aliases(["change-older-than","older"]))
        .arg(Arg::new("owner").short('o').long("owner"))
        .arg(Arg::new("format").long("format"))
        .arg(Arg::new("exec").short('x').long("exec").num_args(1..).allow_hyphen_values(true))
        .arg(Arg::new("exec-batch").short('X').long("exec-batch").num_args(1..).allow_hyphen_values(true))
        .arg(Arg::new("batch-size").long("batch-size").value_parser(value_parser!(usize)).default_value("0"))
        .arg(Arg::new("ignore-file").long("ignore-file"))
        .arg(Arg::new("color").short('c').long("color").default_value("auto").value_parser(["auto","always","never"]))
        .arg(Arg::new("hyperlink").long("hyperlink").num_args(0..=1).require_equals(true).default_missing_value("auto").value_parser(["auto","always","never"]).default_value("never"))
        .arg(Arg::new("ignore-contain").long("ignore-contain").action(ArgAction::Append))
        .arg(Arg::new("threads").short('j').long("threads").value_parser(value_parser!(usize)))
        .arg(Arg::new("max-results").long("max-results").value_parser(value_parser!(usize)))
        .arg(Arg::new("1").short('1').action(ArgAction::SetTrue))
        .arg(Arg::new("quiet").short('q').long("quiet").aliases(["has-results"]).action(ArgAction::SetTrue))
        .arg(Arg::new("show-errors").long("show-errors").action(ArgAction::SetTrue))
        .arg(Arg::new("base-directory").short('C').long("base-directory"))
        .arg(Arg::new("path-separator").long("path-separator"))
        .arg(Arg::new("search-path").long("search-path").action(ArgAction::Append))
        .arg(Arg::new("strip-cwd-prefix").long("strip-cwd-prefix").num_args(0..=1).require_equals(true).default_missing_value("always").value_parser(["auto","always","never"]))
        .arg(Arg::new("one-file-system").long("one-file-system").action(ArgAction::SetTrue))
        ;

    let matches = clap_cmd.get_matches();

    if exec_commands.is_empty() {
        if let Some(exec_vals) = matches.get_many::<String>("exec") {
            let all: Vec<String> = exec_vals.cloned().collect();
            let mut current: Vec<String> = Vec::new();
            for v in all {
                if v == ";" {
                    if !current.is_empty() { exec_commands.push(current.clone()); current.clear(); }
                } else { current.push(v); }
            }
            if !current.is_empty() { exec_commands.push(current); }
        }
    }
    if exec_batch_commands.is_empty() {
        if let Some(exec_vals) = matches.get_many::<String>("exec-batch") {
            let all: Vec<String> = exec_vals.cloned().collect();
            let mut current: Vec<String> = Vec::new();
            for v in all {
                if v == ";" {
                    if !current.is_empty() { exec_batch_commands.push(current.clone()); current.clear(); }
                } else { current.push(v); }
            }
            if !current.is_empty() { exec_batch_commands.push(current); }
        }
    }

    let search_paths: Vec<String> = matches.get_many::<String>("search-path").map(|v| v.cloned().collect()).unwrap_or_default();
    let use_search_path = !search_paths.is_empty();
    let positional_pattern = matches.get_one::<String>("pattern").map(|s| s.clone());
    let positional_paths: Vec<String> = matches.get_many::<String>("path").map(|v| v.cloned().collect()).unwrap_or_default();
    let (pattern_opt, roots) : (Option<String>, Vec<String>) = if use_search_path {
        if !positional_paths.is_empty() {
            eprintln!("error: the argument '--search-path <search-path>' cannot be used with '[path]...'");
            eprintln!("\nUsage: executable --search-path <search-path> <pattern> [path]...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        (positional_pattern.clone(), search_paths.clone())
    } else {
        (positional_pattern.clone(), positional_paths.clone())
    };

    if let Some(_) = matches.get_one::<String>("strip-cwd-prefix") {
        if use_search_path {
            eprintln!("error: the argument '--search-path <search-path>' cannot be used with '--strip-cwd-prefix[=<when>]'");
            eprintln!("\nUsage: executable --search-path <search-path> <pattern> [path]...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        if !roots.is_empty() {
            eprintln!("error: the argument '--strip-cwd-prefix[=<when>]' cannot be used with '[path]...'");
            eprintln!("\nUsage: executable <pattern> <path>...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }

    if let Some(ref pat) = pattern_opt {
        if pat.contains('/') && !matches.get_flag("full-path") && !pat.is_empty() {
            eprintln!("[fd error]: The search pattern '{}' contains a path-separation character ('/') and will not lead to any search results.", pat);
            eprintln!();
            eprintln!("If you want to search for all files inside the '{}' directory, use a match-all pattern:", pat);
            eprintln!();
            eprintln!("  fd . '{}'", pat);
            eprintln!();
            eprintln!("Instead, if you want your pattern to match the full file path, use:");
            eprintln!();
            eprintln!("  fd --full-path '{}'", pat);
            std::process::exit(1);
        }
    }

    if matches.get_flag("fixed-strings") && matches.get_flag("glob") {
        eprintln!("error: the argument '--fixed-strings' cannot be used with '--glob'");
        eprintln!("\nUsage: executable --fixed-strings <pattern> [path]...\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    if matches.get_flag("absolute-path") && matches.get_flag("list-details") {
        eprintln!("error: the argument '--absolute-path' cannot be used with '--list-details'");
        eprintln!("\nUsage: executable --absolute-path [pattern] [path]...\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }
    if matches.get_flag("relative-path") && matches.get_flag("list-details") {
        eprintln!("error: the argument '--relative-path' cannot be used with '--list-details'");
        eprintln!("\nUsage: executable --relative-path [pattern] [path]...\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }

    // last wins handling
    let mut last_hidden: Option<bool> = None;
    let mut last_no_ignore: Option<bool> = None;
    let mut last_no_ignore_vcs: Option<bool> = None;
    let mut last_no_require_git: Option<bool> = None;
    let mut last_no_ignore_parent: Option<bool> = None;
    let mut last_case_sensitive: Option<bool> = None;
    let mut last_ignore_case: Option<bool> = None;
    let mut last_glob: Option<bool> = None;
    let mut last_fixed: Option<bool> = None;
    let mut last_absolute: Option<bool> = None;
    let mut last_relative: Option<bool> = None;
    let mut last_follow: Option<bool> = None;

    for arg in &raw_args {
        match arg.as_str() {
            "-H" | "--hidden" => last_hidden = Some(true),
            "--no-hidden" => last_hidden = Some(false),
            "-I" | "--no-ignore" => last_no_ignore = Some(true),
            "--ignore" => last_no_ignore = Some(false),
            "--no-ignore-vcs" => last_no_ignore_vcs = Some(true),
            "--ignore-vcs" => last_no_ignore_vcs = Some(false),
            "--no-require-git" => last_no_require_git = Some(true),
            "--require-git" => last_no_require_git = Some(false),
            "--no-ignore-parent" => last_no_ignore_parent = Some(true),
            "-s" | "--case-sensitive" => last_case_sensitive = Some(true),
            "-i" | "--ignore-case" => last_ignore_case = Some(true),
            "-g" | "--glob" => { last_glob = Some(true); },
            "--regex" => { last_glob = Some(false); },
            "-F" | "--fixed-strings" => { last_fixed = Some(true); last_glob = Some(false); },
            "-a" | "--absolute-path" => { last_absolute = Some(true); last_relative = Some(false); },
            "--relative-path" => { last_relative = Some(true); last_absolute = Some(false); },
            "-L" | "--follow" => last_follow = Some(true),
            "--no-follow" => last_follow = Some(false),
            _ => {}
        }
    }

    let hidden = if let Some(v) = last_hidden { v } else { matches.get_flag("hidden") } || matches.get_count("unrestricted") > 0;
    let no_ignore = if let Some(v) = last_no_ignore { v } else { matches.get_flag("no-ignore") } || matches.get_count("unrestricted") > 0;
    let no_ignore_vcs = if let Some(v) = last_no_ignore_vcs { v } else { matches.get_flag("no-ignore-vcs") } || matches.get_flag("no-ignore");
    let no_require_git = if let Some(v) = last_no_require_git { v } else { matches.get_flag("no-require-git") };
    let require_git_flag = if let Some(v) = last_no_require_git { !v } else { matches.get_flag("require-git") };
    let no_ignore_parent = if let Some(v) = last_no_ignore_parent { v } else { matches.get_flag("no-ignore-parent") };
    let case_sensitive_flag = if let Some(v) = last_case_sensitive { v } else { matches.get_flag("case-sensitive") };
    let ignore_case_flag = if let Some(v) = last_ignore_case { v } else { matches.get_flag("ignore-case") };
    let glob_flag = if let Some(v) = last_glob { v } else { matches.get_flag("glob") };
    let fixed_flag = if let Some(v) = last_fixed { v } else { matches.get_flag("fixed-strings") };
    let absolute_flag = if let Some(v) = last_absolute { v } else { matches.get_flag("absolute-path") };
    let relative_flag = if let Some(v) = last_relative { v } else { matches.get_flag("relative-path") };
    let follow = if let Some(v) = last_follow { v } else { matches.get_flag("follow") };

    let base_dir_opt = matches.get_one::<String>("base-directory").map(|s| PathBuf::from(s));
    if let Some(ref base) = base_dir_opt {
        if let Err(_) = std::env::set_current_dir(base) {
            eprintln!("[fd error]: Base directory '{}' is not a directory.", base.display());
            std::process::exit(1);
        }
    }

    let search_roots_final: Vec<PathBuf> = if roots.is_empty() { vec![PathBuf::from(".")] } else { roots.iter().map(|s| PathBuf::from(s)).collect() };
    let mut valid_roots: Vec<PathBuf> = Vec::new();
    let mut has_error = false;
    for root in &search_roots_final {
        match fs::metadata(root) {
            Ok(meta) => { if !meta.is_dir() { eprintln!("[fd error]: Search path '{}' is not a directory.", root.display()); has_error=true; } else { valid_roots.push(root.clone()); } },
            Err(_) => { eprintln!("[fd error]: Search path '{}' is not a directory.", root.display()); has_error=true; }
        }
    }
    if has_error && valid_roots.is_empty() { eprintln!("[fd error]: No valid search paths given."); std::process::exit(1); }

    let pattern_str = pattern_opt.clone().unwrap_or_default();
    let is_case_sensitive = if case_sensitive_flag { true } else if ignore_case_flag { false } else { pattern_str.chars().any(|c| c.is_uppercase()) };
    let and_patterns: Vec<String> = matches.get_many::<String>("and").map(|v| v.cloned().collect()).unwrap_or_default();
    let main_regex_opt: Option<Regex> = if pattern_str.is_empty() { None } else {
        if fixed_flag {
            let escaped = regex::escape(&pattern_str);
            let re_str = if is_case_sensitive { escaped } else { format!("(?i){}", escaped) };
            match Regex::new(&re_str) { Ok(r)=>Some(r), Err(e)=>{ eprintln!("[fd error]: {}", e); std::process::exit(1); } }
        } else if glob_flag { None } else {
            let re_str = if is_case_sensitive { pattern_str.clone() } else { format!("(?i){}", pattern_str) };
            match Regex::new(&re_str) { Ok(r)=>Some(r), Err(e)=>{ eprintln!("[fd error]: {}", e); std::process::exit(1); } }
        }
    };
    let mut and_regexes: Vec<Regex> = Vec::new();
    let mut and_globs: Vec<GlobSet> = Vec::new();
    for and_pat in &and_patterns {
        let and_case_sensitive = if case_sensitive_flag { true } else if ignore_case_flag { false } else { and_pat.chars().any(|c| c.is_uppercase()) };
        if fixed_flag {
            let escaped = regex::escape(and_pat);
            let re_str = if and_case_sensitive { escaped } else { format!("(?i){}", escaped) };
            match Regex::new(&re_str) { Ok(r)=>and_regexes.push(r), Err(e)=>{ eprintln!("[fd error]: {}", e); std::process::exit(1); } }
        } else if glob_flag {
            let mut builder = GlobSetBuilder::new();
            let glob = Glob::new(and_pat).unwrap_or_else(|e| { eprintln!("[fd error]: {}", e); std::process::exit(1); });
            builder.add(glob);
            and_globs.push(builder.build().unwrap());
        } else {
            let re_str = if and_case_sensitive { and_pat.clone() } else { format!("(?i){}", and_pat) };
            match Regex::new(&re_str) { Ok(r)=>and_regexes.push(r), Err(e)=>{ eprintln!("[fd error]: {}", e); std::process::exit(1); } }
        }
    }
    let main_globset_opt: Option<GlobSet> = if glob_flag && !pattern_str.is_empty() {
        let mut builder = GlobSetBuilder::new();
        match Glob::new(&pattern_str) {
            Ok(g) => { builder.add(g); match builder.build() { Ok(set)=>Some(set), Err(e)=>{ eprintln!("[fd error]: {}", e); std::process::exit(1); } } },
            Err(e) => { eprintln!("[fd error]: {}", e); std::process::exit(1); }
        }
    } else { None };
    let max_depth = if let Some(d) = matches.get_one::<usize>("max-depth") { Some(*d) } else if let Some(d) = matches.get_one::<usize>("exact-depth") { Some(*d) } else { None };
    let min_depth = if let Some(d) = matches.get_one::<usize>("min-depth") { Some(*d) } else if let Some(d) = matches.get_one::<usize>("exact-depth") { Some(*d) } else { None };
    let type_filters_raw: Vec<String> = matches.get_many::<String>("type").map(|v| v.cloned().collect()).unwrap_or_default();
    let mut type_filters: Vec<FileTypeFilter> = Vec::new();
    for t in type_filters_raw {
        if let Some(f) = parse_file_type(&t) { type_filters.push(f); } else {
            eprintln!("error: invalid value '{}' for '--type <filetype>'", t);
            eprintln!("  [possible values: file, directory, symlink, block-device, char-device, executable, empty, socket, pipe]");
            eprintln!("\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }
    let ext_filters_raw: Vec<String> = matches.get_many::<String>("extension").map(|v| v.cloned().collect()).unwrap_or_default();
    let mut ext_filters: Vec<String> = Vec::new();
    for e in ext_filters_raw {
        let mut ext = e;
        if ext.starts_with('.') { ext = ext[1..].to_string(); }
        ext_filters.push(ext.to_lowercase());
    }
    let exclude_patterns_raw: Vec<String> = matches.get_many::<String>("exclude").map(|v| v.cloned().collect()).unwrap_or_default();
    let mut exclude_globset: Option<GlobSet> = None;
    if !exclude_patterns_raw.is_empty() {
        let mut builder = GlobSetBuilder::new();
        for pat in &exclude_patterns_raw {
            let glob = Glob::new(pat).unwrap_or_else(|e| { eprintln!("[fd error]: {}", e); std::process::exit(1); });
            builder.add(glob);
        }
        exclude_globset = Some(builder.build().unwrap());
    }
    let size_filters_raw: Vec<String> = matches.get_many::<String>("size").map(|v| v.cloned().collect()).unwrap_or_default();
    let mut size_filters: Vec<SizeFilter> = Vec::new();
    for s in size_filters_raw {
        match parse_size(&s) {
            Ok(f) => size_filters.push(f),
            Err(e) => {
                eprintln!("error: invalid value '{}' for '--size <size>': {}", s, e);
                eprintln!("\nFor more information, try '--help'.");
                std::process::exit(2);
            }
        }
    }
    let changed_within_raw = matches.get_one::<String>("changed-within").map(|s| s.clone());
    let changed_before_raw = matches.get_one::<String>("changed-before").map(|s| s.clone());
    let changed_within_dt: Option<DateTime<Utc>> = if let Some(ref s) = changed_within_raw {
        match parse_time_filter(s) { Ok(dt) => Some(dt), Err(e) => { eprintln!("[fd error]: {}", e); std::process::exit(1); } }
    } else { None };
    let changed_before_dt: Option<DateTime<Utc>> = if let Some(ref s) = changed_before_raw {
        match parse_time_filter(s) { Ok(dt) => Some(dt), Err(e) => { eprintln!("[fd error]: {}", e); std::process::exit(1); } }
    } else { None };
    let owner_raw = matches.get_one::<String>("owner").map(|s| s.clone());
    let owner_filter: Option<OwnerFilter> = if let Some(ref s) = owner_raw {
        match parse_owner(s) {
            Ok(f) => Some(f),
            Err(e) => {
                eprintln!("error: invalid value '{}' for '--owner <user:group>': {}", s, e);
                eprintln!("\nFor more information, try '--help'.");
                std::process::exit(2);
            }
        }
    } else { None };
    let color_when = matches.get_one::<String>("color").unwrap().clone();
    let hyperlink_when = matches.get_one::<String>("hyperlink").unwrap().clone();
    let print0 = matches.get_flag("print0");
    let is_absolute = if relative_flag { false } else if absolute_flag { true } else { false };
    let path_sep = matches.get_one::<String>("path-separator").map(|s| s.clone()).unwrap_or_else(|| std::path::MAIN_SEPARATOR.to_string());
    let format_opt = matches.get_one::<String>("format").map(|s| s.clone());
    let list_details = matches.get_flag("list-details");
    let follow = matches.get_flag("follow");
    let prune = matches.get_flag("prune");
    let one_file_system = matches.get_flag("one-file-system");
    let show_errors = matches.get_flag("show-errors");
    let max_results_opt = if matches.get_flag("1") { Some(1) } else { matches.get_one::<usize>("max-results").cloned() };
    let quiet = matches.get_flag("quiet");
    let ignore_file_opt = matches.get_one::<String>("ignore-file").map(|s| s.clone());
    let ignore_contain: Vec<String> = matches.get_many::<String>("ignore-contain").map(|v| v.cloned().collect()).unwrap_or_default();
    let batch_size = matches.get_one::<usize>("batch-size").cloned().unwrap_or(0);
    let use_color = match color_when.as_str() { "always"=>true, "never"=>false, "auto"=>false, _=>false };
    let use_hyperlink = match hyperlink_when.as_str() { "always"=>true, "never"=>false, "auto"=>use_color, _=>false };

    let roots_empty = roots.is_empty();

    let mut results: Vec<PathBuf> = Vec::new();
    let mut pruned_dirs: Vec<PathBuf> = Vec::new();
    for root in &valid_roots {
        let mut builder = WalkBuilder::new(root);
        builder.hidden(!hidden);
        if no_ignore {
            builder.ignore(false); builder.git_ignore(false); builder.git_global(false); builder.git_exclude(false); builder.require_git(false);
        } else if no_ignore_vcs {
            builder.git_ignore(false); builder.git_global(false); builder.git_exclude(false); builder.ignore(true);
        } else {
            builder.ignore(true); builder.git_ignore(true); builder.git_global(true); builder.git_exclude(true);
            if no_require_git { builder.require_git(false); } else if require_git_flag { builder.require_git(true); } else { builder.require_git(true); }
        }
        if no_ignore_parent { builder.parents(false); } else { builder.parents(true); }
        builder.follow_links(follow);
        if let Some(md) = max_depth { builder.max_depth(Some(md)); }
        if let Some(ref ignore_file) = ignore_file_opt { builder.add_ignore(Path::new(ignore_file)); }
        if one_file_system { builder.same_file_system(true); }
        if let Some(threads) = matches.get_one::<usize>("threads") { builder.threads(*threads); }
        let walker = builder.build();
        for entry in walker {
            let entry = match entry {
                Ok(e) => e,
                Err(err) => { if show_errors { eprintln!("[fd error]: {}", err); } continue; }
            };
            let path = entry.path().to_path_buf();
            let depth = entry.depth();
            if depth==0 { continue; }
            if let Some(min_d) = min_depth { if depth < min_d { continue; } }
            if prune {
                let mut skip = false;
                for pd in &pruned_dirs { if path.starts_with(pd) && path != *pd { skip=true; break; } }
                if skip { continue; }
            }
            let mut should_ignore_contain = false;
            if !ignore_contain.is_empty() {
                for anc in path.ancestors().skip(1) {
                    for ic_name in &ignore_contain {
                        let candidate = anc.join(ic_name);
                        if candidate.exists() { should_ignore_contain=true; break; }
                    }
                    if should_ignore_contain { break; }
                }
                if !should_ignore_contain && path.is_dir() {
                    for ic_name in &ignore_contain { if path.join(ic_name).exists() { should_ignore_contain=true; break; } }
                }
            }
            if should_ignore_contain { continue; }
            if let Some(ref excl_set) = exclude_globset {
                let file_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
                let path_str = path.to_string_lossy();
                let mut is_excluded = false;
                if excl_set.is_match(file_name) || excl_set.is_match(path_str.as_ref()) { is_excluded=true; }
                if !is_excluded {
                    for anc in path.ancestors().skip(1) {
                        if let Some(fname) = anc.file_name().and_then(|n| n.to_str()) { if excl_set.is_match(fname) { is_excluded=true; break; } }
                        if excl_set.is_match(anc.to_string_lossy().as_ref()) { is_excluded=true; break; }
                    }
                }
                if is_excluded { continue; }
            }
            let meta = match fs::symlink_metadata(&path) { Ok(m)=>m, Err(_)=>{ continue; } };
            if !type_filters.is_empty() {
                let mut type_match = false;
                for tf in &type_filters {
                    match tf {
                        FileTypeFilter::File => { if meta.is_file() { type_match=true; } },
                        FileTypeFilter::Directory => { if meta.is_dir() { type_match=true; } },
                        FileTypeFilter::Symlink => { if meta.file_type().is_symlink() { type_match=true; } },
                        FileTypeFilter::Executable => { if meta.is_file() { let mode=meta.mode(); if mode & 0o111 !=0 { type_match=true; } } },
                        FileTypeFilter::Empty => {
                            if meta.is_file() { if meta.len()==0 { type_match=true; } }
                            else if meta.is_dir() { if let Ok(rd)=fs::read_dir(&path) { if rd.count()==0 { type_match=true; } } }
                        },
                        FileTypeFilter::Socket => { let mode=meta.mode(); if mode & 0o170000 == 0o140000 { type_match=true; } },
                        FileTypeFilter::Pipe => { let mode=meta.mode(); if mode & 0o170000 == 0o10000 { type_match=true; } },
                        FileTypeFilter::BlockDevice => { let mode=meta.mode(); if mode & 0o170000 == 0o60000 { type_match=true; } },
                        FileTypeFilter::CharDevice => { let mode=meta.mode(); if mode & 0o170000 == 0o20000 { type_match=true; } },
                    }
                }
                if !type_match { continue; }
            }
            if !ext_filters.is_empty() {
                if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
                    let ext_lower = ext.to_lowercase();
                    if !ext_filters.contains(&ext_lower) { continue; }
                } else { continue; }
            }
            if !size_filters.is_empty() {
                if !meta.is_file() { continue; }
                let file_size = meta.len();
                let mut size_ok = true;
                for sf in &size_filters {
                    match sf.kind {
                        '+' => { if file_size < sf.size { size_ok=false; break; } },
                        '-' => { if file_size > sf.size { size_ok=false; break; } },
                        '=' => { if file_size != sf.size { size_ok=false; break; } },
                        _ => {}
                    }
                }
                if !size_ok { continue; }
            }
            if let Some(ref within_dt) = changed_within_dt {
                let mtime = meta.mtime() as i64;
                let mtime_dt = Utc.timestamp_opt(mtime, 0).unwrap();
                if mtime_dt < *within_dt { continue; }
            }
            if let Some(ref before_dt) = changed_before_dt {
                let mtime = meta.mtime() as i64;
                let mtime_dt = Utc.timestamp_opt(mtime, 0).unwrap();
                if mtime_dt > *before_dt { continue; }
            }
            if let Some(ref of) = owner_filter { if !check_owner(&meta, of) { continue; } }
            let match_target = if matches.get_flag("full-path") {
                match path.canonicalize() { Ok(p)=>p.to_string_lossy().to_string(), Err(_)=>path.to_string_lossy().to_string() }
            } else {
                path.file_name().and_then(|n| n.to_str()).unwrap_or("").to_string()
            };
            let mut matched = false;
            if pattern_str.is_empty() { matched=true; }
            else if glob_flag {
                if let Some(ref set) = main_globset_opt { matched=set.is_match(&match_target); }
            } else {
                if let Some(ref re) = main_regex_opt { matched=re.is_match(&match_target); }
            }
            if !matched { continue; }
            let mut and_ok = true;
            for (idx, _) in and_patterns.iter().enumerate() {
                let target = if matches.get_flag("full-path") {
                    match path.canonicalize() { Ok(p)=>p.to_string_lossy().to_string(), Err(_)=>path.to_string_lossy().to_string() }
                } else { path.file_name().and_then(|n| n.to_str()).unwrap_or("").to_string() };
                if glob_flag {
                    if idx < and_globs.len() { if !and_globs[idx].is_match(&target) { and_ok=false; break; } }
                } else {
                    if idx < and_regexes.len() { if !and_regexes[idx].is_match(&target) { and_ok=false; break; } }
                }
            }
            if !and_ok { continue; }
            results.push(path.clone());
            if prune && path.is_dir() { pruned_dirs.push(path.clone()); }
        }
    }
    results.sort();
    if let Some(max) = max_results_opt { if results.len() > max { results.truncate(max); } }
    if quiet { if results.is_empty() { std::process::exit(1); } else { std::process::exit(0); } }

    if !exec_commands.is_empty() || !exec_batch_commands.is_empty() {
        let use_null_sep = print0;
        let strip_cwd_prefix_opt = matches.get_one::<String>("strip-cwd-prefix").map(|s| s.clone());
        let strip_for_exec = if let Some(val) = strip_cwd_prefix_opt {
            match val.as_str() { "always"=>true, "never"=>false, "auto"=>false, _=>false }
        } else {
            if roots_empty { false } else { true }
        };
        let batch_size_val = batch_size;

        if !exec_batch_commands.is_empty() {
            for batch_cmd_template in &exec_batch_commands {
                let has_placeholder = batch_cmd_template.iter().any(|arg| arg.contains("{}") || arg.contains("{/}") || arg.contains("{//}") || arg.contains("{.}") || arg.contains("{/.}"));
                let mut cmd_template = batch_cmd_template.clone();
                if !has_placeholder { cmd_template.push("{}".to_string()); }
                let mut placeholder_kinds: std::collections::HashSet<String> = std::collections::HashSet::new();
                for arg in &cmd_template {
                    if arg.contains("{}") { placeholder_kinds.insert("{}".to_string()); }
                    if arg.contains("{/}") { placeholder_kinds.insert("{/}".to_string()); }
                    if arg.contains("{//}") { placeholder_kinds.insert("{//}".to_string()); }
                    if arg.contains("{.}") { placeholder_kinds.insert("{.}".to_string()); }
                    if arg.contains("{/.}") { placeholder_kinds.insert("{/.}".to_string()); }
                }
                if placeholder_kinds.len() > 1 {
                    eprintln!("error: Only one placeholder allowed for batch commands");
                    eprintln!("\nUsage: fd [OPTIONS] [pattern] [path]...\n\nFor more information, try '--help'.");
                    std::process::exit(2);
                }
                let batches: Vec<Vec<PathBuf>> = if batch_size_val == 0 {
                    vec![results.clone()]
                } else {
                    let mut b: Vec<Vec<PathBuf>> = Vec::new();
                    let mut current: Vec<PathBuf> = Vec::new();
                    for r in &results {
                        current.push(r.clone());
                        if current.len() >= batch_size_val {
                            b.push(current.clone());
                            current.clear();
                        }
                    }
                    if !current.is_empty() { b.push(current); }
                    b
                };
                for batch in batches {
                    let mut exec_args: Vec<String> = Vec::new();
                    for template_arg in &cmd_template {
                        if template_arg.contains("{}") || template_arg.contains("{/}") || template_arg.contains("{//}") || template_arg.contains("{.}") || template_arg.contains("{/.}") {
                            for res_path in &batch {
                                let expanded = expand_placeholder(template_arg, res_path, &path_sep, is_absolute, strip_for_exec, roots_empty);
                                exec_args.push(expanded);
                            }
                        } else {
                            let esc = template_arg.replace("{{", "{").replace("}}", "}");
                            exec_args.push(esc);
                        }
                    }
                    if exec_args.is_empty() { continue; }
                    let cmd_name = exec_args[0].clone();
                    let cmd_args = &exec_args[1..];
                    let mut child = process::Command::new(cmd_name).args(cmd_args).spawn().unwrap_or_else(|e| { eprintln!("Failed to execute: {}", e); std::process::exit(1); });
                    let _ = child.wait();
                }
            }
        }

        if !exec_commands.is_empty() {
            for res_path in &results {
                for exec_cmd_template in &exec_commands {
                    let has_placeholder = exec_cmd_template.iter().any(|arg| arg.contains("{}") || arg.contains("{/}") || arg.contains("{//}") || arg.contains("{.}") || arg.contains("{/.}"));
                    let mut cmd_template = exec_cmd_template.clone();
                    if !has_placeholder { cmd_template.push("{}".to_string()); }
                    let mut exec_args: Vec<String> = Vec::new();
                    for template_arg in &cmd_template {
                        let expanded = expand_placeholder(template_arg, res_path, &path_sep, is_absolute, strip_for_exec, roots_empty);
                        exec_args.push(expanded);
                    }
                    if exec_args.is_empty() { continue; }
                    let cmd_name = exec_args[0].clone();
                    let cmd_args = &exec_args[1..];
                    let mut child = process::Command::new(cmd_name).args(cmd_args).spawn().unwrap_or_else(|e| { eprintln!("Failed to execute: {}", e); std::process::exit(1); });
                    let _ = child.wait();
                    if use_null_sep {
                        print!("\0");
                        use std::io::Write;
                        std::io::stdout().flush().unwrap();
                    }
                }
            }
        }
        return;
    }

    if list_details {
        let mut sorted = results.clone(); sorted.sort();
        let mut cmd_ls = process::Command::new("ls");
        cmd_ls.arg("-l"); cmd_ls.arg("-d");
        for p in &sorted {
            let mut out_path = if is_absolute {
                match p.canonicalize() { Ok(pp)=>pp.to_string_lossy().to_string(), Err(_)=>p.to_string_lossy().to_string() }
            } else {
                let s = p.to_string_lossy().to_string();
                if s.starts_with("./") { s } else { format!("./{}", s) }
            };
            if path_sep != std::path::MAIN_SEPARATOR.to_string() { out_path = out_path.replace(std::path::MAIN_SEPARATOR, &path_sep); }
            cmd_ls.arg(out_path);
        }
        let output = cmd_ls.output().expect("failed to execute ls");
        print!("{}", String::from_utf8_lossy(&output.stdout));
        if !output.stderr.is_empty() { eprint!("{}", String::from_utf8_lossy(&output.stderr)); }
        return;
    }

    let strip_cwd_prefix_opt = matches.get_one::<String>("strip-cwd-prefix").map(|s| s.clone());
    let strip_cwd_prefix = if let Some(val) = strip_cwd_prefix_opt {
        match val.as_str() {
            "always"=>true,
            "never"=>false,
            "auto"=>{ if print0 || !exec_commands.is_empty() || !exec_batch_commands.is_empty() { if roots_empty { false } else { true } } else { true } },
            _=>true
        }
    } else {
        if print0 || !exec_commands.is_empty() || !exec_batch_commands.is_empty() {
            if roots_empty { false } else { true }
        } else { true }
    };
    for res_path in &results {
        let mut out_path: String;
        if is_absolute {
            match res_path.canonicalize() { Ok(p)=>out_path=p.to_string_lossy().to_string(), Err(_)=>out_path=res_path.to_string_lossy().to_string() }
        } else {
            let s = res_path.to_string_lossy().to_string();
            let mut tmp = if s.starts_with("./") { s[2..].to_string() } else { s };
            if !strip_cwd_prefix {
                if !tmp.starts_with("./") && !tmp.starts_with("/") { tmp = format!(".{}{}", path_sep, tmp); }
            }
            out_path = tmp;
        }
        if path_sep != std::path::MAIN_SEPARATOR.to_string() { out_path = out_path.replace(std::path::MAIN_SEPARATOR, &path_sep); }
        let is_dir = res_path.is_dir();
        if is_dir && !out_path.ends_with(&path_sep) { out_path.push_str(&path_sep); }
        if let Some(ref fmt) = format_opt {
            let formatted = apply_format(fmt, res_path, &path_sep, is_absolute);
            if print0 {
                let mut p0 = formatted.clone();
                if !strip_cwd_prefix && !is_absolute {
                    if !p0.starts_with("./") && !p0.starts_with("/") { p0 = format!(".{}{}", path_sep, p0); }
                }
                print!("{}\0", p0);
            } else { println!("{}", formatted); }
        } else {
            let mut display_path = out_path.clone();
            if use_hyperlink {
                let abs_path = match res_path.canonicalize() { Ok(p)=>p, Err(_)=>{ let cwd=std::env::current_dir().unwrap_or(PathBuf::from(".")); cwd.join(res_path) } };
                let hostname = get_hostname();
                let url = format!("file://{}{}", hostname, abs_path.to_string_lossy());
                if use_color {
                    let colored = colorize_path(&res_path, &display_path);
                    display_path = format!("\x1b]8;;{}\x1b\\{}\x1b]8;;\x1b\\", url, colored);
                } else {
                    display_path = format!("\x1b]8;;{}\x1b\\{}\x1b]8;;\x1b\\", url, display_path);
                }
            } else if use_color {
                display_path = colorize_path(&res_path, &display_path);
            }
            if print0 { print!("{}\0", display_path); } else { println!("{}", display_path); }
        }
    }
}
